def compute_percentiles_nummath(T1, low=0, high=100, seed=None):
    """
    Convert elements in T1 (tuple of tuples of strings) to integers,
    create a list of random integers whose length equals the sum of those integers,
    and return the 25th, 50th, and 75th percentiles of that list.

    Parameters:
    - T1: tuple of tuples (or other nested iterable) containing string representations of integers
    - low: inclusive lower bound for random integers (default 0)
    - high: inclusive upper bound for random integers (default 100)
    - seed: optional seed for reproducible randomness

    Returns:
    - (p25, p50, p75): tuple of floats representing the 25th, 50th, and 75th percentiles

    Notes:
    - This function is self-contained and exposes an internal 'nummath' helper that
      provides the required random-list generation and percentile calculation.
    """
    import random
    import math

    # --- tiny internal 'nummath' implementation used by this function ---
    class nummath:
        @staticmethod
        def randint_list(size, low_val, high_val):
            if size < 0:
                raise ValueError("size must be non-negative")
            return [random.randint(low_val, high_val) for _ in range(size)]

        @staticmethod
        def percentile(data, p):
            if not data:
                raise ValueError("cannot compute percentile of empty data")
            if not (0 <= p <= 100):
                raise ValueError("percentile must be between 0 and 100")
            a = sorted(data)
            n = len(a)
            # position in the sorted array using linear interpolation (numpy-like)
            pos = (p / 100.0) * (n - 1)
            lo = int(math.floor(pos))
            hi = int(math.ceil(pos))
            if lo == hi:
                return float(a[lo])
            w = pos - lo
            return float(a[lo] * (1 - w) + a[hi] * w)
    # --- end of internal nummath ---

    # Optional reproducible randomness
    if seed is not None:
        random.seed(seed)

    # Flatten T1 and convert strings to ints
    try:
        flattened = []
        for row in T1:
            for item in row:
                flattened.append(int(item))
    except Exception as e:
        raise ValueError("T1 must be a nested iterable of strings representing integers") from e

    total_size = sum(flattened)
    if total_size <= 0:
        raise ValueError("sum of integers must be positive to create a list of random integers")

    # Create the random integer list using nummath
    rand_list = nummath.randint_list(total_size, low, high)

    # Compute percentiles
    p25 = nummath.percentile(rand_list, 25.0)
    p50 = nummath.percentile(rand_list, 50.0)
    p75 = nummath.percentile(rand_list, 75.0)

    return (p25, p50, p75)

