                    for ai in addrinfos:
                        if ai[0] == socket.AF_INET6:
                            chosen_ip = ai[4][0]
                            break
            if not chosen_ip:
                result["error"] = "Could not resolve host to an IP address."
                return result
            ip = chosen_ip
        except socket.gaierror as e:
            result["error"] = f"DNS resolution failed: {e}"
            return result
        except Exception as e:
            result["error"] = f"Unexpected error during DNS resolution: {e}"
            return result

    result["ip"] = ip

