    attempt = 0
    last_exception = None
    while attempt < retries:
        attempt += 1
        try:
            resp = _http_get(base_url, timeout)
        except Exception as e:
            # Network-level or library-level exception; consider retrying
            last_exception = e
            # exponential backoff before retrying
            if attempt < retries:
                sleep_for = backoff_factor * (2 ** (attempt - 1))
                time.sleep(sleep_for)
                continue
            else:
                result["error"] = f"Network error while contacting geolocation service: {e}"
                return result

        # Attempt to gather status code and body in a robust manner
        status_code = None
        text_body = None
        try:
            status_code = getattr(resp, "status_code", None)
            # Some alternative libs may store response text in .text or .content; try both
            if hasattr(resp, "text"):
                text_body = resp.text
            else:
                text_body = getattr(resp, "content", None)
                if isinstance(text_body, bytes):
                    try:
                        text_body = text_body.decode("utf-8", errors="replace")
                    except Exception:
                        text_body = str(text_body)
        except Exception:
            text_body = None

        result["raw_response"] = text_body

        # If status code is None, treat as failure
        if status_code is None:
            last_exception = Exception("HTTP client did not provide a status code.")
            if attempt < retries:
                time.sleep(backoff_factor * (2 ** (attempt - 1)))
                continue
            else:
                result["error"] = "Failed to obtain HTTP response status; see raw_response."
                return result

        # Handle 200 OK
        if 200 <= status_code < 300:
            # Parse JSON body robustly
            try:
                if hasattr(resp, "json"):
                    # requests has .json(); unknown libs might as well
                    data = resp.json()
                else:
                    # fallback to parsing the text body
                    data = json.loads(text_body) if text_body else {}
                result["geo"] = data
                result["error"] = None
                return result
            except Exception as e:
                result["error"] = f"Failed to parse JSON from geolocation service: {e}"
                return result

        # Handle rate limiting
        if status_code == 429:
            # Try to get Retry-After header if available
            retry_after = None
            try:
                if hasattr(resp, "headers"):
                    retry_after = resp.headers.get("Retry-After")
                else:
                    # some libs may expose headers differently
                    headers = getattr(resp, "headers", None)
                    if isinstance(headers, dict):
                        retry_after = headers.get("Retry-After")
            except Exception:
                retry_after = None

            if retry_after:
                try:
                    wait = int(retry_after)
                except Exception:
                    # If header is a date or unparseable, use exponential backoff instead
                    wait = backoff_factor * (2 ** (attempt - 1))
            else:
                wait = backoff_factor * (2 ** (attempt - 1))

            if attempt < retries:
                time.sleep(wait)
                continue
            else:
                result["error"] = f"Rate limited by geolocation service (HTTP 429)."
                return result

        # 5xx server errors -> retry
        if 500 <= status_code < 600:
            if attempt < retries:
                time.sleep(backoff_factor * (2 ** (attempt - 1)))
                continue
            else:
                result["error"] = f"Server error from geolocation service: HTTP {status_code}"
                return result

        # Client errors (4xx other than 429) -> give up and return the message
        try:
            # try to include error details from body if present
            detail = ""
            if text_body:
                detail = f": {text_body.strip()}"
        except Exception:
            detail = ""
        result["error"] = f"Geolocation service returned HTTP {status_code}{detail}"
        return result

    # If we exit loop without returning, put last exception
    result["error"] = f"Exhausted retries; last error: {last_exception}"
    return result
