                req = _ur.Request(url, headers={"User-Agent": "resolve_and_geolocate/1.0"})
                try:
                    with _ur.urlopen(req, timeout=timeout) as fh:
                        raw = fh.read()
                        status = fh.getcode()
                        text = raw.decode("utf-8", errors="replace")
                        return _NormalizedResponse(status, text)
                except _ue.URLError as e:
                    raise ConnectionError(str(e)) from e

    class _NormalizedResponse:
        def __init__(self, status_code, text):
            self.status_code = status_code
            self.text = text

        @classmethod
        def from_requests(cls, r):
            return cls(r.status_code, r.text)

        @classmethod
        def from_raw(cls, raw):
            # Try to introspect common attributes used by requests-like libs
            status = getattr(raw, "status_code", None) or getattr(raw, "status", None)
            text = None
            # try .text, then .content, then .read()
            if hasattr(raw, "text"):
                text = raw.text
            elif hasattr(raw, "content"):
                try:
                    text = raw.content.decode("utf-8", errors="replace")
                except Exception:
                    text = str(raw.content)
            elif hasattr(raw, "read"):
                try:
                    b = raw.read()
                    if isinstance(b, bytes):
                        text = b.decode("utf-8", errors="replace")
                    else:
                        text = str(b)
                except Exception:
                    text = None
            return cls(status, text)

        def json(self):
            # parse self.text as JSON
            if self.text is None:
                raise ValueError("No response text to parse as JSON")
            return json.loads(self.text)

    # --- helper: resolve host to an IP string ---
    def _resolve_host(h):
        # If it's already an IP, use it (validates IPv4 and IPv6)
        try:
            ip_obj = ipaddress.ip_address(h)
            return str(ip_obj)
        except Exception:
            pass

        # Not a literal IP — try DNS resolution (both IPv4 and IPv6)
        try:
            # getaddrinfo may return many entries; prefer IPv4 results first, then IPv6
            infos = socket.getaddrinfo(h, None, proto=socket.IPPROTO_TCP)
            # iterate to find first suitable address
            for fam, socktype, proto, canonname, sockaddr in infos:
                # sockaddr is a tuple: (ip, port) for IPv4, (ip, port, flowinfo, scopeid) for IPv6
                if isinstance(sockaddr, tuple) and len(sockaddr) >= 1:
                    ip_candidate = sockaddr[0]
                    # validate
                    try:
                        ip_obj = ipaddress.ip_address(ip_candidate)
                        return str(ip_obj)
                    except Exception:
                        continue
            raise socket.gaierror(f"No usable IP addresses found for host: {h}")
        except socket.gaierror as e:
            raise

    # --- main flow ---
    result = {"success": False, "ip": None, "data": None, "status_code": None, "error": None}

    # Resolve host
    try:
        ip = _resolve_host(host)
        result["ip"] = ip
    except socket.gaierror as e:
        result["error"] = f"DNS resolution failed: {e}"
        return result
    except Exception as e:
        result["error"] = f"Unexpected error resolving host: {e}"
        return result

    # Prepare HTTP client
    client = _HttpClient()

    # Build ipinfo url
    url = f"https://ipinfo.io/{ip}/json"

    # Retry loop
    last_exception = None
    for attempt in range(1, max_retries + 2):  # +1 to allow initial try + max_retries retries
        try:
            resp = client.get(url, timeout=timeout)
            status = resp.status_code if resp.status_code is not None else 0
            result["status_code"] = status

            # Consider transient errors: 5xx and 429 -> retry
            if 500 <= status < 600 or status == 429:
                if attempt <= max_retries:
                    sleep_for = backoff_factor * (2 ** (attempt - 1))
                    time.sleep(sleep_for)
                    continue
                else:
                    result["error"] = f"Geolocation service returned status {status}"
                    return result

            # 4xx errors (other than 429) are likely client/invalid IP — return without retrying
            if 400 <= status < 500:
                # try to extract a helpful message
                try:
                    payload = resp.json()
                    msg = payload.get("error") or payload.get("message") or payload
                    result["error"] = f"Geolocation service returned {status}: {msg}"
                except Exception:
                    result["error"] = f"Geolocation service returned status {status}"
                return result

            # status 200-ish: try parse JSON
            try:
                data = resp.json()
                # ipinfo sometimes returns an 'error' field even with 200; treat that as an error
                if isinstance(data, dict) and ("error" in data or "bogon" in data):
                    # return but mark as not successful
                    err_detail = data.get("error") or data.get("bogon")
                    result["data"] = data
                    result["error"] = f"Geolocation service returned an error response: {err_detail}"
                    return result
                result["data"] = data
                result["success"] = True
                return result
            except json.JSONDecodeError as e:
                # Bad JSON from server
                result["error"] = f"Failed to parse JSON from geolocation service: {e}"
                return result

        except ConnectionError as e:
            last_exception = e
            if attempt <= max_retries:
                sleep_for = backoff_factor * (2 ** (attempt - 1))
                time.sleep(sleep_for)
                continue
            else:
                result["error"] = f"Network error while contacting geolocation service: {e}"
                return result
        except Exception as e:
            # Unexpected exception from HTTP layer or wrapper parsing
            last_exception = e
            if attempt <= max_retries:
                time.sleep(backoff_factor * (2 ** (attempt - 1)))
                continue
            result["error"] = f"Unexpected error while contacting geolocation service: {e}"
            return result

    # If loop exits without returning, we had repeated failures
    if last_exception:
        result["error"] = f"Failed after retries: {last_exception}"
    else:
        result["error"] = "Failed to contact geolocation service for unknown reasons"
    return result


