def draw_linear_equation_matplotplus():
    """
    Draws y = 2x + 1 for x in [-10, 10] using the `matplotplus` API.
    If the matplotplus library is not installed, a small compatibility
    wrapper around matplotlib is used automatically.

    Plot features:
    - Red line for y = 2x + 1, labeled 'y=2x+1'
    - Green 'o' marker for the solution at x = 2 (y = 5), labeled 'solution at x=2'
    - Title: 'Solution of the equation y=2x+1 at x=2'
    - X-axis labeled 'x' with range [-10, 10]
    - Y-axis labeled 'y' with automatic range
    - Legend included
    """
    try:
        import matplotplus as mpp  # try to use real matplotplus if available
    except Exception:
        # Fallback wrapper using matplotlib with a matplotplus-like interface
        import matplotlib.pyplot as plt

        class _MatplotPlusFallback:
            @staticmethod
            def figure(*args, **kwargs):
                return plt.figure(*args, **kwargs)

            @staticmethod
            def plot(x, y, *args, **kwargs):
                return plt.plot(x, y, *args, **kwargs)

            @staticmethod
            def scatter(x, y, *args, **kwargs):
                return plt.scatter(x, y, *args, **kwargs)

            @staticmethod
            def title(txt, *args, **kwargs):
                return plt.title(txt, *args, **kwargs)

            @staticmethod
            def xlabel(txt, *args, **kwargs):
                return plt.xlabel(txt, *args, **kwargs)

            @staticmethod
            def ylabel(txt, *args, **kwargs):
                return plt.ylabel(txt, *args, **kwargs)

            @staticmethod
            def xlim(a, b, *args, **kwargs):
                return plt.xlim(a, b, *args, **kwargs)

            @staticmethod
            def ylim(*args, **kwargs):
                return plt.ylim(*args, **kwargs)

            @staticmethod
            def legend(*args, **kwargs):
                return plt.legend(*args, **kwargs)

            @staticmethod
            def show(*args, **kwargs):
                return plt.show(*args, **kwargs)

        mpp = _MatplotPlusFallback()

    import numpy as np

    # Prepare data
    x = np.linspace(-10, 10, 400)
    y = 2 * x + 1

    # Create plot
    mpp.figure()
    mpp.plot(x, y, color='red', label='y=2x+1')
    # Mark the solution at x=2, y=5 with a green circle 'o'
    mpp.scatter([2], [5], color='green', marker='o', s=60, label='solution at x=2')

