    mpp.xlabel('x')
    mpp.ylabel('y')
    mpp.xlim(-10, 10)  # set x-axis range as required
    # Do not set ylim to allow automatic adjustment based on data

    # Legend and show
    mpp.legend()
    mpp.show()


