                            return _ERResponseWrapper2(resp.getcode())
                    except urllib.error.HTTPError as e:
                        # HTTPError contains the HTTP status code (e.g. 404, 500)
                        return _ERResponseWrapper2(e.code)
                    # Other exceptions (URLError, etc.) will propagate to caller

            er = _EasyRequestsShimUR

    results = []
    try:
        network = ipaddress.ip_network(cidr, strict=False)
    except Exception as e:
        raise ValueError(f"Invalid CIDR '{cidr}': {e}")

    for ip in network.hosts():
        ip_str = str(ip)
        # For IPv6 literal in URL, wrap in brackets per RFC
        if ip.version == 6:
            url = f"http://[{ip_str}]/"
        else:
            url = f"http://{ip_str}/"

        try:
            resp = er.get(url, timeout=timeout)
            # Some shims/wrappers return objects with .status_code
            if hasattr(resp, "status_code") and resp.status_code == 200:
                results.append(ip_str)
        except Exception:
            # On any error (timeout, connection refused, DNS, etc.) ignore and continue
            continue

    return results
```

