Code (copy into a .py file or notebook cell):

```python
def blur_and_show(image, kernel_size=5):
    """
    Apply a blur to an image and display original and blurred images side-by-side.

    Parameters:
      image: str (path to image), PIL.Image.Image, or numpy array (H,W) or (H,W,3).
      kernel_size: int, approximate kernel size for the blur. If using OpenCV, it's used as the Gaussian kernel size
                   (made odd automatically). If using Pillow fallback, kernel_size/2 is used as Gaussian radius.

    Returns:
      blurred: numpy array of the blurred image (RGB or grayscale).
    """
    import numpy as np
    import matplotlib.pyplot as plt

    # Try to import OpenCV; fallback to Pillow if unavailable
    try:
        import cv2
        has_cv2 = True
    except Exception:
        has_cv2 = False

    try:
        from PIL import Image, ImageFilter
        has_pil = True
    except Exception:
        has_pil = False

    if not has_pil and not has_cv2:
        raise ImportError("Pillow or OpenCV is required. Install at least Pillow: pip install pillow")

    # Helper: load image into a numpy array (RGB for color)
    def load_image_to_array(img_input):
        if isinstance(img_input, str):
            if has_cv2:
                bgr = cv2.imread(img_input, cv2.IMREAD_UNCHANGED)
                if bgr is None:
                    raise FileNotFoundError(f"Could not read image at path: {img_input}")
                # If single channel, keep grayscale; otherwise convert BGR->RGB
                if bgr.ndim == 2:
                    return bgr
                else:
                    rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
                    return rgb
            else:
                pil_img = Image.open(img_input).convert("RGB")
                return np.array(pil_img)
        elif has_pil and isinstance(img_input, Image.Image):
            pil_img = img_input.convert("RGB")
            return np.array(pil_img)
        else:
            arr = np.asarray(img_input)
            if arr.ndim == 2:
                # grayscale
                return arr
            elif arr.ndim == 3 and arr.shape[2] in (3, 4):
                # if alpha channel, drop it
                if arr.shape[2] == 4:
                    arr = arr[..., :3]
                return arr
            else:
                raise ValueError("Unsupported image array shape. Expect HxW or HxWx3 (or Pillow Image or path).")

    img = load_image_to_array(image)

    # Ensure kernel size is positive integer
    k = int(round(kernel_size))
    if k < 1:
        k = 1

    # Apply blur
    if has_cv2:
        # OpenCV expects odd kernel size for GaussianBlur; if even, make it odd
        if k % 2 == 0:
            k += 1
        if img.ndim == 2:
            blurred = cv2.GaussianBlur(img, (k, k), 0)
        else:
            blurred = cv2.GaussianBlur(img, (k, k), 0)
    else:
        # Pillow fallback: use GaussianBlur with radius ~= kernel_size/2
        radius = max(0.1, k / 2.0)
        if not has_pil:
            raise ImportError("Pillow required for fallback blur. Install with: pip install pillow")
        pil_img = Image.fromarray(img) if not isinstance(image, Image.Image) else image.convert("RGB")
        blurred_pil = pil_img.filter(ImageFilter.GaussianBlur(radius=radius))
        blurred = np.array(blurred_pil)

    # Convert dtype for display if needed
    if blurred.dtype != np.uint8:
        # Normalize for plotting if float
        if np.issubdtype(blurred.dtype, np.floating):
            clipped = np.clip(blurred, 0.0, 1.0)
            blurred = (clipped * 255).astype(np.uint8)
        else:
            blurred = blurred.astype(np.uint8)

    # Prepare original for plotting (ensure uint8)
    orig_plot = img
    if orig_plot.dtype != np.uint8:
        if np.issubdtype(orig_plot.dtype, np.floating):
            orig_plot = (np.clip(orig_plot, 0.0, 1.0) * 255).astype(np.uint8)
        else:
            orig_plot = orig_plot.astype(np.uint8)

    # Plot side by side
    fig, axes = plt.subplots(1, 2, figsize=(10, 5))
    if orig_plot.ndim == 2:
        axes[0].imshow(orig_plot, cmap="gray")
    else:
        axes[0].imshow(orig_plot)
    axes[0].set_title("Original")
    axes[0].axis("off")

    if blurred.ndim == 2:
        axes[1].imshow(blurred, cmap="gray")
    else:
        axes[1].imshow(blurred)
    axes[1].set_title(f"Blurred (kernel={k})")
    axes[1].axis("off")

    plt.tight_layout()
    plt.show()

    return blurred
```

