It looks like "openpyxcel" is a misspelling (there is no such package). I used the standard package openpyxl for .xlsx files and xlrd for old .xls files. Below is a self-contained Python function that converts an Excel file (.xls or .xlsx) to a CSV, with options to specify a different destination path (or directory), choose a sheet by name or index, and set the CSV delimiter.

Requirements:
- pip install openpyxl xlrd

Function:

```python
import os
import csv
import datetime

def excel_to_csv(excel_path, csv_path=None, sheet_name=None, sheet_index=0, delimiter=',', date_format='%Y-%m-%d %H:%M:%S'):
    """
    Convert an Excel file (.xls or .xlsx) to a CSV file.

    Parameters:
    - excel_path: path to the Excel file (.xls or .xlsx).
    - csv_path: path to output CSV file OR directory. If None, CSV will be created next to the Excel file,
                with the same basename and .csv extension.
    - sheet_name: optional sheet name to convert. If provided, sheet_index is ignored.
    - sheet_index: index of sheet to convert if sheet_name is not provided (default: 0).
    - delimiter: CSV delimiter (default: ',').
    - date_format: format string used to format datetime values.

    Returns:
    - path to the written CSV file.

    Raises:
    - FileNotFoundError if excel_path doesn't exist.
    - ValueError for unsupported extensions or invalid sheet selection.
    - ImportError if required libraries are not installed.
    """
    if not os.path.isfile(excel_path):
        raise FileNotFoundError(f"Excel file not found: {excel_path}")

    base_name = os.path.splitext(os.path.basename(excel_path))[0]
    if csv_path is None:
        csv_path = os.path.join(os.path.dirname(excel_path), base_name + '.csv')
    elif os.path.isdir(csv_path):
        csv_path = os.path.join(csv_path, base_name + '.csv')

    ext = os.path.splitext(excel_path)[1].lower()

    def _format_value(val):
        if val is None:
            return ''
        if isinstance(val, bool):
            return 'TRUE' if val else 'FALSE'
        if isinstance(val, (int, float)):
            # Avoid scientific notation unintended formatting for floats that are actually integers
            if isinstance(val, float) and val.is_integer():
                return str(int(val))
            return str(val)
        if isinstance(val, (datetime.datetime, datetime.date, datetime.time)):
            # datetime and date -> formatted
            try:
                return val.strftime(date_format)
            except Exception:
                return str(val)
        return str(val)

    if ext == '.xlsx':
        try:
            import openpyxl
        except Exception as e:
            raise ImportError("openpyxl is required to read .xlsx files. Install with 'pip install openpyxl'") from e

        wb = openpyxl.load_workbook(excel_path, read_only=True, data_only=True)
        # choose sheet
        if sheet_name is not None:
            if sheet_name not in wb.sheetnames:
                raise ValueError(f"Sheet name '{sheet_name}' not found in workbook")
            ws = wb[sheet_name]
        else:
            if sheet_index < 0 or sheet_index >= len(wb.sheetnames):
                raise ValueError(f"sheet_index {sheet_index} out of range (0..{len(wb.sheetnames)-1})")
            ws = wb[wb.sheetnames[sheet_index]]

        with open(csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f, delimiter=delimiter)
            for row in ws.iter_rows(values_only=True):
                writer.writerow([_format_value(cell) for cell in row])

        wb.close()
        return csv_path

    elif ext == '.xls':
        try:
            import xlrd
        except Exception as e:
            raise ImportError("xlrd is required to read .xls files. Install with 'pip install xlrd'") from e

        book = xlrd.open_workbook(excel_path)
        if sheet_name is not None:
            try:
                sheet = book.sheet_by_name(sheet_name)
            except xlrd.biffh.XLRDError:
                raise ValueError(f"Sheet name '{sheet_name}' not found in workbook")
        else:
            if sheet_index < 0 or sheet_index >= book.nsheets:
                raise ValueError(f"sheet_index {sheet_index} out of range (0..{book.nsheets-1})")
            sheet = book.sheet_by_index(sheet_index)

        with open(csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f, delimiter=delimiter)
            for r in range(sheet.nrows):
                row_vals = []
                for c in range(sheet.ncols):
                    cell = sheet.cell(r, c)
                    ctype = cell.ctype
                    cval = cell.value
                    # xlrd date handling: type 3 is XL_CELL_DATE
                    if ctype == xlrd.XL_CELL_DATE:
                        try:
                            dt = xlrd.xldate_as_datetime(cval, book.datemode)
                            row_vals.append(dt.strftime(date_format))
                        except Exception:
                            row_vals.append(str(cval))
                    elif ctype == xlrd.XL_CELL_EMPTY or ctype == xlrd.XL_CELL_BLANK:
                        row_vals.append('')
                    elif ctype == xlrd.XL_CELL_BOOLEAN:
                        row_vals.append('TRUE' if cval else 'FALSE')
                    elif ctype == xlrd.XL_CELL_NUMBER:
                        # keep ints without decimal when appropriate
                        if isinstance(cval, float) and cval.is_integer():
                            row_vals.append(str(int(cval)))
                        else:
                            row_vals.append(str(cval))
                    else:
                        row_vals.append(str(cval))
                writer.writerow(row_vals)

        return csv_path

    else:
        raise ValueError("Unsupported file extension. Only .xls and .xlsx are supported.")
```

Example usage:
- Convert in-place (same directory, same base name): excel_to_csv("data.xlsx")
- Convert and place CSV in another directory: excel_to_csv("data.xls", csv_path="/tmp/exports/")
- Convert a specific sheet by name: excel_to_csv("book.xlsx", sheet_name="Sheet2")

