    def _is_nan(x):
        return isinstance(x, float) and math.isnan(x)

    numeric_values = []
    age_labels = []
    for row in data_list:
        # row may be dict-like
        try:
            val = row.get(column) if isinstance(row, dict) else getattr(row, column, None)
        except Exception:
            val = None
        if _is_number(val):
            numeric_values.append(float(val))
            # Age label
            try:
                age_val = row.get('Age') if isinstance(row, dict) else getattr(row, 'Age', None)
                age_labels.append(str(age_val) if age_val is not None else '')
            except Exception:
                age_labels.append('')
        else:
            # skip non-numeric values for the target column
            continue

    if not numeric_values:
        stats = {'sum': 0.0, 'mean': NAN, 'min': NAN, 'max': NAN}
        used_count = 0
    else:
        total = float(sum(numeric_values))
        used_count = len(numeric_values)
        mean = float(total / used_count)
        minimum = float(min(numeric_values))
        maximum = float(max(numeric_values))
        stats = {'sum': total, 'mean': mean, 'min': minimum, 'max': maximum}

    if show_plot:
        if used_count == 0:
            plt.figure()
            plt.pie([1], labels=['No numeric data'], colors=['#dddddd'])
            plt.title(f'Pie chart for {column} (no numeric data)')
            plt.show()
        else:
            sizes = [abs(float(x)) for x in numeric_values]
            if sum(sizes) == 0:
                sizes = [1 for _ in sizes]
            labels = age_labels if age_labels else [str(i) for i in range(len(sizes))]
            plt.figure()
            plt.pie(sizes, labels=labels, autopct='%1.1f%%')
            plt.title(f'Pie chart for {column}')
            plt.show()

    return stats, used_count

