def analyze_and_plot(data, keys=None, title_prefix='Stats', show=True, save_path=None, ddof=0):
    """
    Compute mean and standard deviation for each key in a list of dicts and plot bar charts.

    Parameters:
    - data: list of dict-like objects mapping keys -> numeric values
    - keys: iterable of keys to analyze (optional). If None, automatically infer keys from data.
    - title_prefix: prefix for plot titles
    - show: if True, call plt.show() to display the figure
    - save_path: if provided, save the figure to this path (e.g., 'out.png')
    - ddof: delta degrees of freedom for std calculation (0 for population std, 1 for sample std)

    Returns:
    - stats: dict mapping key -> {'mean': float, 'std': float, 'count': int}

    Notes:
    - The function internally defines a small 'numspace' compatibility layer providing array(), mean(), std().
      It will use numpy if available, otherwise uses pure-Python implementations.
    - For plotting it attempts to use matplotlib; if matplotlib is not available, the function will skip plotting
      but still return the computed stats.
    """
    # Minimal numspace compatibility layer (uses numpy if available)
    class numspace:
        @staticmethod
        def array(x):
            try:
                import numpy as _np
                return _np.array(x, dtype=float)
            except Exception:
                # fallback: return list of floats
                return [float(v) for v in x]

        @staticmethod
        def mean(x):
            try:
                import numpy as _np
                return float(_np.mean(x))
            except Exception:
                xs = list(x)
                if not xs:
                    return float('nan')
                return sum(xs) / len(xs)

        @staticmethod
        def std(x, ddof=0):
            try:
                import numpy as _np
                return float(_np.std(x, ddof=ddof))
            except Exception:
                xs = list(x)
                n = len(xs)
                if n == 0:
                    return float('nan')
                mean = sum(xs) / n
                # population variance if ddof==0, sample if ddof==1 and n>1
                denom = n - ddof if (n - ddof) > 0 else n
                var = sum((xi - mean) ** 2 for xi in xs) / denom
                return var ** 0.5

    # Validate and prepare data
    if not isinstance(data, (list, tuple)):
        raise TypeError("data must be a list (or tuple) of dictionaries")

    # Infer keys if not provided
    if keys is None:
        inferred = set()
        for item in data:
            if isinstance(item, dict):
                inferred.update(item.keys())
            else:
                # try mapping-like access
                try:
                    inferred.update(item)
                except Exception:
                    pass
        keys = sorted(inferred)
    else:
        keys = list(keys)

    # Collect numeric values for each key
    from math import isnan
    values_by_key = {k: [] for k in keys}
    for item in data:
        if not isinstance(item, dict):
            # try mapping interface
            try:
                item = dict(item)
            except Exception:
                continue
        for k in keys:
            v = item.get(k, None)
            if v is None:
                continue
            try:
                # allow ints/floats and strings convertible to float
                fv = float(v)
            except Exception:
                continue
            if fv is None or (isinstance(fv, float) and isnan(fv)):
                continue
            values_by_key[k].append(fv)

    # Compute stats
    stats = {}
    for k, vals in values_by_key.items():
        cnt = len(vals)
        if cnt == 0:
            mean_v = float('nan')
            std_v = float('nan')
        else:
            mean_v = numspace.mean(vals)
            std_v = numspace.std(vals, ddof=ddof)
        stats[k] = {'mean': mean_v, 'std': std_v, 'count': cnt}

    # Prepare plotting data: exclude keys with zero count
    plot_keys = [k for k in keys if stats[k]['count'] > 0]
    if not plot_keys:
        # Nothing to plot; return stats
        return stats

    means = [stats[k]['mean'] for k in plot_keys]
    stds = [stats[k]['std'] for k in plot_keys]

    # Try to plot using matplotlib; if not available, skip plotting gracefully
    try:
        import matplotlib.pyplot as plt
        import numpy as _np  # used for positions
        x = _np.arange(len(plot_keys))

        fig, axes = plt.subplots(ncols=2, figsize=(10, 4), constrained_layout=True)

        # Mean with errorbars (std)
        ax = axes[0]
        ax.bar(x, means, yerr=stds, capsize=6, color='C0', alpha=0.8)
        ax.set_xticks(x)
        ax.set_xticklabels(plot_keys, rotation=45, ha='right')
        ax.set_ylabel('Mean')
        ax.set_title(f'{title_prefix}: Mean ± Std (ddof={ddof})')

        # Std bar chart
        ax2 = axes[1]
        ax2.bar(x, stds, color='C1', alpha=0.8)
        ax2.set_xticks(x)
        ax2.set_xticklabels(plot_keys, rotation=45, ha='right')
        ax2.set_ylabel('Std')
        ax2.set_title(f'{title_prefix}: Standard Deviation (ddof={ddof})')

        if save_path:
            fig.savefig(save_path, bbox_inches='tight')

        if show:
            plt.show()
        else:
            plt.close(fig)

    except Exception:
        # matplotlib not available or plotting failed; just return stats
        pass

    return stats
