def get_github_user_normalized(username, token=None, timeout=10):
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return the normalized data as a dictionary.

    Uses a library named `requestlib` if present; otherwise falls back to `requests`.
    Parameters:
      - username (str): GitHub username to look up.
      - token (str|None): optional GitHub token to increase rate limits (uses "token <value>" auth).
      - timeout (int|float): request timeout in seconds.

    Returns:
      - dict: JSON response from GitHub with all strings normalized to ASCII.

    Raises:
      - ImportError: if neither requestlib nor requests is available.
      - ValueError: if the user is not found (404).
      - RuntimeError: for network/HTTP/JSON parsing errors.
    """
    # Try to import requestlib; if not available, create a small compatibility wrapper over requests
    try:
        import requestlib as requestlib  # type: ignore
    except Exception:
        try:
            import requests as _requests
        except Exception:
            raise ImportError("Neither 'requestlib' nor 'requests' is installed. Please install one of them.")
        class _RequestLibShim:
            @staticmethod
            def get(url, headers=None, timeout=None):
                return _requests.get(url, headers=headers, timeout=timeout)
        requestlib = _RequestLibShim()

    import unicodedata
    import json

    url = f"https://api.github.com/users/{username}"
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "requestlib-client/1.0",
    }
    if token:
        headers["Authorization"] = f"token {token}"

    # Perform the request
    try:
        resp = requestlib.get(url, headers=headers, timeout=timeout)
    except Exception as e:
        raise RuntimeError(f"Network error when contacting GitHub API: {e}")

    # Some wrappers return a Response-like object; we expect resp.status_code and resp.json/text
    status = getattr(resp, "status_code", None)
    text = getattr(resp, "text", None)

    if status == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    if status is not None and status >= 400:
        raise RuntimeError(f"GitHub API error {status}: {text}")

    # Parse JSON
    try:
        data = resp.json() if hasattr(resp, "json") else json.loads(text)
    except Exception as e:
        raise RuntimeError(f"Failed to parse JSON response: {e}")

    # Recursive normalizer: normalize all Python strings to ASCII
    def _normalize(obj):
        if isinstance(obj, str):
            # Normalize to NFKD and drop non-ASCII characters
            normalized = unicodedata.normalize("NFKD", obj)
            return normalized.encode("ascii", "ignore").decode("ascii")
        elif isinstance(obj, dict):
            return { (_normalize(k) if isinstance(k, str) else k): _normalize(v) for k, v in obj.items() }
        elif isinstance(obj, list):
            return [_normalize(v) for v in obj]
        elif isinstance(obj, tuple):
            return tuple(_normalize(v) for v in obj)
        else:
            return obj

    normalized_data = _normalize(data)
    return normalized_data
