    if status == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    if status < 200 or status >= 300:
        # try to get text for message
        text = ""
        try:
            text = resp.text
        except Exception:
            try:
                text = resp.content.decode("utf-8", errors="replace")
            except Exception:
                text = "<no response body available>"
        raise RuntimeError(f"GitHub API returned status {status}: {text}")

    # parse JSON
    try:
        data = resp.json()
    except Exception:
