Both normalize a 2D numeric array (matrix) by Z-score. By default they normalize per-column (axis=0). You can set axis=1 to normalize per-row or axis=None to normalize the whole matrix. Columns or rows with zero standard deviation are left as zeros (to avoid division by zero). NaN values are preserved.

Copy whichever implementation fits your environment.

1) NumPy-backed implementation (recommended):

```python
def zscore_normalize(matrix, axis=0, ddof=0):
    """
    Z-score normalize a 2D numeric array (matrix).

    Parameters:
    - matrix: 2D array-like (list of lists or numpy array).
    - axis: 0 to normalize columns (default), 1 to normalize rows, or None to normalize entire matrix.
    - ddof: delta degrees of freedom for std calculation (passed to numpy.nanstd).

    Returns:
    - numpy.ndarray with same shape as input, dtype=float, where each value is (x-mean)/std.
      For groups (columns/rows) with zero std, result values are set to 0.
      NaNs in the input are preserved.
    """
    try:
        import numpy as np
    except ImportError:
        raise ImportError("NumPy is required for this implementation. If you don't have NumPy, use the pure-Python fallback.")

    arr = np.asarray(matrix, dtype=float)
    if arr.ndim != 2:
        raise ValueError("Input must be a 2D array or sequence of sequences.")

    if axis is None:
        mean = np.nanmean(arr)
        std = np.nanstd(arr, ddof=ddof)
        if std == 0 or np.isnan(std):
            # If std is zero (or degenerate), return zeros but keep NaNs
            res = np.where(np.isnan(arr), np.nan, 0.0)
        else:
            res = (arr - mean) / std
        return res

    if axis not in (0, 1):
        raise ValueError("axis must be 0, 1, or None")

    mean = np.nanmean(arr, axis=axis, keepdims=True)
    std = np.nanstd(arr, axis=axis, ddof=ddof, keepdims=True)

    # Avoid division by zero: replace zeros with 1 for safe division, then fix those places to 0
    zero_mask = (std == 0) | np.isnan(std)
    safe_std = np.where(zero_mask, 1.0, std)
    normalized = (arr - mean) / safe_std
    # For groups where std was zero/NaN, set normalized values (except NaNs) to 0
    if np.any(zero_mask):
        if axis == 0:
            cols_with_zero = zero_mask.reshape(1, -1).astype(bool)
            normalized = np.where(np.isnan(arr), np.nan, normalized)
            normalized[:, cols_with_zero.flatten()] = np.where(
                np.isnan(arr[:, cols_with_zero.flatten()]), np.nan, 0.0
            )
        else:  # axis == 1
            rows_with_zero = zero_mask.reshape(-1, 1).astype(bool)
            normalized = np.where(np.isnan(arr), np.nan, normalized)
            normalized[rows_with_zero.flatten(), :] = np.where(
                np.isnan(arr[rows_with_zero.flatten(), :]), np.nan, 0.0
            )

    return normalized
```

