def _is_nan(x):
    try:
        import math
        return math.isnan(x)
    except Exception:
        return False

def zscore_normalize_pure(matrix, axis=0, ddof=0):
    """
    Pure-Python Z-score normalization for a 2D numeric list of lists.

    Parameters same as zscore_normalize. Returns a list of lists (floats).
    """
    # Validate and convert to list of lists
    if not matrix:
        return []
    rows = [list(row) for row in matrix]
    n_rows = len(rows)
    n_cols = len(rows[0])
    for r in rows:
        if len(r) != n_cols:
            raise ValueError("All rows must have the same length")

    import math

    def col_stats(col_idx):
        vals = []
        for r in range(n_rows):
            v = rows[r][col_idx]
            if v is None:
                vals.append(float('nan'))
            else:
                try:
                    fv = float(v)
                    if not math.isnan(fv):
                        vals.append(fv)
                except Exception:
                    pass
        if not vals:
            return (float('nan'), float('nan'))
        mean = sum(vals) / len(vals)
        # population std by default (ddof=0)
        var = sum((x - mean) ** 2 for x in vals) / (len(vals) - ddof if (len(vals)-ddof) > 0 else 1)
        std = math.sqrt(var)
        return mean, std

    def row_stats(row_idx):
        vals = []
        for c in range(n_cols):
            v = rows[row_idx][c]
            if v is None:
                vals.append(float('nan'))
            else:
                try:
                    fv = float(v)
                    if not math.isnan(fv):
                        vals.append(fv)
                except Exception:
                    pass
        if not vals:
            return (float('nan'), float('nan'))
        mean = sum(vals) / len(vals)
        var = sum((x - mean) ** 2 for x in vals) / (len(vals) - ddof if (len(vals)-ddof) > 0 else 1)
        std = math.sqrt(var)
        return mean, std

    # Prepare output matrix of floats (with NaNs preserved)
    out = [[None] * n_cols for _ in range(n_rows)]

    if axis is None:
        # Flattened stats
        flat = []
        for r in range(n_rows):
            for c in range(n_cols):
                try:
                    v = float(rows[r][c])
                    if not math.isnan(v):
                        flat.append(v)
                except Exception:
                    pass
        if not flat:
            return [[float('nan')]*n_cols for _ in range(n_rows)]
        mean = sum(flat) / len(flat)
        var = sum((x-mean)**2 for x in flat) / (len(flat)-ddof if (len(flat)-ddof) > 0 else 1)
        std = math.sqrt(var)
        if std == 0 or math.isnan(std):
            for r in range(n_rows):
                for c in range(n_cols):
                    v = rows[r][c]
                    try:
                        fv = float(v)
                        out[r][c] = float('nan') if math.isnan(fv) else 0.0
                    except Exception:
                        out[r][c] = float('nan')
            return out
        for r in range(n_rows):
            for c in range(n_cols):
                try:
                    fv = float(rows[r][c])
                    out[r][c] = float('nan') if math.isnan(fv) else (fv - mean) / std
                except Exception:
                    out[r][c] = float('nan')
        return out

    if axis == 0:  # columns
        stats = [col_stats(c) for c in range(n_cols)]
        for r in range(n_rows):
            for c in range(n_cols):
                v = rows[r][c]
                try:
                    fv = float(v)
                    if math.isnan(fv):
                        out[r][c] = float('nan')
                    else:
                        mean, std = stats[c]
                        if std == 0 or math.isnan(std):
                            out[r][c] = 0.0
                        else:
                            out[r][c] = (fv - mean) / std
                except Exception:
                    out[r][c] = float('nan')
        return out

    if axis == 1:  # rows
        stats = [row_stats(r) for r in range(n_rows)]
        for r in range(n_rows):
            mean, std = stats[r]
            for c in range(n_cols):
                v = rows[r][c]
                try:
                    fv = float(v)
                    if math.isnan(fv):
                        out[r][c] = float('nan')
                    else:
                        if std == 0 or math.isnan(std):
                            out[r][c] = 0.0
                        else:
                            out[r][c] = (fv - mean) / std
                except Exception:
                    out[r][c] = float('nan')
        return out

    raise ValueError("axis must be 0, 1, or None")
