import datetime
import random

# Try to use zoneinfo (Python 3.9+). If not available, try pytz.
try:
    import zoneinfo
    ZoneInfo = zoneinfo.ZoneInfo
    available_timezones = getattr(zoneinfo, "available_timezones", None)
except Exception:
    ZoneInfo = None
    available_timezones = None

try:
    import pytz
except Exception:
    pytz = None

# Fallback list of common timezones if a full tz DB isn't available
FALLBACK_ZONES = [
    "UTC",
    "Europe/London",
    "Europe/Paris",
    "Europe/Berlin",
    "America/New_York",
    "America/Chicago",
    "America/Denver",
    "America/Los_Angeles",
    "America/Sao_Paulo",
    "America/Toronto",
    "Asia/Tokyo",
    "Asia/Shanghai",
    "Asia/Hong_Kong",
    "Asia/Kolkata",
    "Asia/Dubai",
    "Australia/Sydney",
]

def _get_zone(zone_name):
    """Return a zone object usable for tz-aware conversions."""
    if ZoneInfo is not None:
        return ZoneInfo(zone_name)
    elif pytz is not None:
        return pytz.timezone(zone_name)
    else:
        raise RuntimeError(
            "No timezone support available. Install Python 3.9+ (zoneinfo) or the 'pytz' package."
        )

def _list_timezones():
    """Return an iterable of timezone names. Prefer full DB if available."""
    if available_timezones:
        try:
            # available_timezones() may return a set-like object
            zones = sorted(available_timezones())
            if zones:
                return zones
        except Exception:
            pass
    if pytz is not None:
        return list(pytz.all_timezones)
    return FALLBACK_ZONES

def convert_datetime_to_random_timezone(dt_string, from_tz=None, fmt=None, out_fmt=None):
    """
    Convert dt_string (in the timezone `from_tz` if dt_string is naive) to a randomly chosen timezone.
    Returns (converted_datetime_string, chosen_timezone_name).

    - dt_string: input datetime string.
    - from_tz: required if dt_string has no timezone info; should be an IANA name like "America/New_York".
    - fmt: optional strptime format used to parse dt_string. If None, tries ISO-8601 then "%Y-%m-%d %H:%M:%S".
    - out_fmt: optional strftime format for output. If None, uses ISO-8601 via .isoformat().

    Examples:
      convert_datetime_to_random_timezone("2023-05-01T12:30:00", from_tz="Europe/London")
      convert_datetime_to_random_timezone("2023-05-01 12:30:00", from_tz="UTC", fmt="%Y-%m-%d %H:%M:%S")
    """
    if ZoneInfo is None and pytz is None:
        raise RuntimeError("No timezone library available. Use Python 3.9+ or install pytz.")

    # Parse input datetime
    dt = None
    if fmt:
        dt = datetime.datetime.strptime(dt_string, fmt)
    else:
        s = dt_string
        # Handle trailing Z for UTC in ISO8601
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            # fallback common format
            try:
                dt = datetime.datetime.strptime(dt_string, "%Y-%m-%d %H:%M:%S")
            except Exception as e:
                raise ValueError(
                    "Could not parse dt_string. Provide a 'fmt' or use an ISO-8601 string "
                    "or 'YYYY-MM-DD HH:MM:SS'."
                ) from e

    # If parsed dt has no tzinfo, we need from_tz
    if dt.tzinfo is None:
        if not from_tz:
            raise ValueError(
                "Input datetime is naive (no timezone). Please provide from_tz (e.g. 'America/New_York')."
            )
        src_zone_obj = _get_zone(from_tz)
        # For zoneinfo, set tzinfo via replace; for pytz, localize if available
        if ZoneInfo is not None:
            dt = dt.replace(tzinfo=src_zone_obj)
            src_tz_name = from_tz
        else:
            # pytz
            dt = pytz.timezone(from_tz).localize(dt)
            src_tz_name = from_tz
    else:
        # dt already has tzinfo; prefer its zone name if available
        # Note: zoneinfo.ZoneInfo tzinfo .key gives IANA name; pytz tzinfo has zone attribute
        try:
            if isinstance(dt.tzinfo, zoneinfo.ZoneInfo):
                src_tz_name = getattr(dt.tzinfo, "key", None) or str(dt.tzinfo)
            else:
                src_tz_name = getattr(dt.tzinfo, "zone", None) or str(dt.tzinfo)
        except Exception:
            src_tz_name = str(dt.tzinfo)

    # Choose a random timezone, trying to avoid picking the same as source
    zones = list(_list_timezones())
    if not zones:
        zones = FALLBACK_ZONES[:]
    # Ensure unique choice when possible
    choices = [z for z in zones if z != src_tz_name]
    if not choices:
        choices = zones
    target_tz = random.choice(choices)

    target_zone_obj = _get_zone(target_tz)

    # Convert
    if ZoneInfo is not None:
        converted = dt.astimezone(target_zone_obj)
    else:
        # pytz: astimezone works with pytz timezone objects
        converted = dt.astimezone(target_zone_obj)

    # Format output
    if out_fmt:
        out_str = converted.strftime(out_fmt)
    else:
        # Use ISO-8601 output including offset
        out_str = converted.isoformat()

    return out_str, target_tz

