```python
import re
from typing import List

def extract_english_words(text: str, n: int) -> List[str]:
    """
    Extract up to n distinct English words from text, ignoring case.
    The text is split into word-like tokens (letters and apostrophes),
    only English words are retained. If fewer than n distinct English
    words are found, return all distinct ones.

    Strategy:
    - Preserve the order of first appearance.
    - Try to use 'nltkit' if it exists (expected to provide a boolean check).
    - Else try NLTK (WordNet and words corpus) if available.
    - Else fall back to a conservative alphabetic-only heuristic.
    """
    if n <= 0:
        return []

    # Tokenize into words (letters and apostrophes). This keeps contractions like "don't".
    tokens = re.findall(r"[A-Za-z']+", text)
    seen = set()
    candidates = []
    for t in tokens:
        w = t.lower()
        if w not in seen:
            seen.add(w)
            candidates.append(w)

    # Try using nltkit if present (user-requested). We do a safe dynamic call:
    def is_english_with_nltkit(w: str) -> bool:
        try:
            import nltkit  # attempt import
        except Exception:
            return None  # signal not available
        # We don't know exact nltkit API; try a few plausible function names.
        for attr in ("is_english", "is_english_word", "is_englishword", "is_english_word?"):
            func = getattr(nltkit, attr, None)
            if callable(func):
                try:
                    return bool(func(w))
                except Exception:
                    pass
        # try a generic `lang` module or classifier inside nltkit
        try:
            # e.g., nltkit.lang.is_english
            lang = getattr(nltkit, "lang", None)
            if lang:
                func = getattr(lang, "is_english", None) or getattr(lang, "is_english_word", None)
                if callable(func):
                    return bool(func(w))
        except Exception:
            pass
        # If no suitable API found, signal unavailable (None) so we fall back
        return None

    # Try NLTK checks if nltkit not usable
    nltk_available = False
    use_wordnet = False
    use_words_corpus = False
    word_set = None
    try:
        import nltk
        nltk_available = True
        # Try WordNet
        try:
            from nltk.corpus import wordnet as wn
            # ensure WordNet is downloaded
            try:
                wn.ensure_loaded()
                use_wordnet = True
            except Exception:
                # attempt to download if not present
                try:
                    nltk.download('wordnet', quiet=True)
                    wn.ensure_loaded()
                    use_wordnet = True
                except Exception:
                    use_wordnet = False
        except Exception:
            use_wordnet = False

        # Try words corpus
        try:
            from nltk.corpus import words as words_corpus
            try:
                # ensure words corpus is loaded
                word_list = words_corpus.words()
                word_set = set(w.lower() for w in word_list)
                use_words_corpus = True
            except Exception:
                try:
                    nltk.download('words', quiet=True)
                    word_list = words_corpus.words()
                    word_set = set(w.lower() for w in word_list)
                    use_words_corpus = True
                except Exception:
                    use_words_corpus = False
        except Exception:
            use_words_corpus = False
    except Exception:
        nltk_available = False

    def is_english_with_nltk(w: str) -> bool:
        # prefer WordNet (synsets) if available because it's robust for lemmas
        if use_wordnet:
            try:
                from nltk.corpus import wordnet as wn
                if wn.synsets(w):
                    return True
                # also try lemma forms (simple heuristic)
                # e.g., plural to singular not handled here; WordNet often contains base forms
            except Exception:
                pass
        if use_words_corpus and word_set is not None:
            if w in word_set:
                return True
            # also try simple stripping of apostrophes for contractions
            if "'" in w:
                if w.replace("'", "") in word_set:
                    return True
        return False

    def is_english_heuristic(w: str) -> bool:
        # conservative: alphabetic only, length >= 2 (single letters like 'a' are English but many single letters are not desired)
        # keep 'a' and 'i' though as they are valid English words
        if w in ("a", "i"):
            return True
        return w.isalpha() and len(w) >= 2

    results = []
    # First check whether nltkit is usable
    nltkit_possible = False
    try:
        nltkit_check = is_english_with_nltkit  # call to detect availability
        # test with a known English word to detect if we have a callable implementation
        probe = nltkit_check("test")
        if probe is None:
            nltkit_possible = False
        else:
            nltkit_possible = True
    except Exception:
        nltkit_possible = False

    for w in candidates:
        if len(results) >= n:
            break
        is_eng = False

        if nltkit_possible:
            try:
                val = is_english_with_nltkit(w)
                if val is True:
                    is_eng = True
                elif val is False:
                    is_eng = False
                else:
                    # val is None -> treat as unknown and fall through to nltk/heuristic
                    pass
            except Exception:
                pass

        if not is_eng:
            # try NLTK if available
            if nltk_available:
                try:
                    if is_english_with_nltk(w):
                        is_eng = True
                except Exception:
                    is_eng = False

        if not is_eng:
            # fall back to heuristic
            if is_english_heuristic(w):
                is_eng = True

        if is_eng:
            results.append(w)

    return results
