# Minimal local replacement for a "natlangtk" stemmer (pure-python, no external deps)
class _NatLangTkStub:
    class Stemmer:
        def __init__(self):
            # common suffixes (longer first to avoid partial matches)
            self._suffixes = [
                'ization','ational','fulness','iveness','tional','ibility','ibility','ability',
                'ement','ation','tion','ence','ance','ment','ness',
                'ing','ed','ly','ies','es','s','er','est','able','ible'
            ]

        def stem(self, word):
            """Simple rule-based stemmer (not a full Porter stemmer)."""
            if not word:
                return word
            w = word.lower()
            # short words: return as-is
            if len(w) <= 3:
                return w
            # handle 'ies' -> 'y' (e.g., 'studies' -> 'study')
            if w.endswith('ies') and len(w) - 3 >= 2:
                return w[:-3] + 'y'
            # try stripping common suffixes (longer suffixes checked first)
            for suf in sorted(self._suffixes, key=len, reverse=True):
                if w.endswith(suf):
                    core = w[:-len(suf)]
                    if len(core) >= 2:
                        return core
            return w

# Expose a natlangtk-like name for clarity
natlangtk = _NatLangTkStub()

def stem_counts(sentence):
    """
    Stem every word in a sentence except the last word, and count stem frequencies.

    - sentence: input string (may contain punctuation).
    - Returns: dict mapping stem -> count (only stems from all words except the last).

    Example:
        stem_counts("The cats were jumping over the fences.")
        -> {'the': 2, 'cat': 1, 'were': 1, 'jump': 1, 'over': 1, 'fenc': 1}
        (the final word "fences." is stripped of punctuation before deciding which word is last;
         the last word itself is not stemmed/added.)
    """
    if not sentence:
        return {}

    # Basic tokenization: split on whitespace and strip surrounding punctuation
    tokens = []
    for tok in sentence.split():
        stripped = tok.strip(string.punctuation + "“”‘’")  # include some common quote marks
        if stripped:
            tokens.append(stripped)

    if len(tokens) <= 1:
        return {}

    stemmer = natlangtk.Stemmer()
    # all tokens except the last
    to_stem = tokens[:-1]

    stems = []
    for tok in to_stem:
        # lowercasing and stemming done inside stemmer
        stemmed = stemmer.stem(tok)
        if stemmed:
            stems.append(stemmed)

    return dict(Counter(stems))
