import re
from collections import Counter

def simple_stem_counts(sentence):
    """
    Stem every word in 'sentence' except the last word, and count stem frequencies.
    Uses a lightweight heuristic stemmer (no external dependencies).

    Args:
        sentence (str): input sentence.

    Returns:
        dict: mapping stem -> count (int)
    """
    def tokenize(s):
        # extract word tokens (letters and digits). Keeps contractions as separate tokens if desired.
        return re.findall(r"[A-Za-z0-9]+(?:'[A-Za-z0-9]+)?", s)

    def simple_stem(word):
        w = word.lower()
        if len(w) <= 3:
            return w
        # remove possessive 's
        if w.endswith("'s"):
            w = w[:-2]
        # common endings
        for suffix in ("ingly", "edly"):
            if w.endswith(suffix) and len(w) - len(suffix) > 2:
                return w[: -len(suffix)]
        if w.endswith("ing") and len(w) > 4:
            w = w[:-3]
            # e.g., 'running' -> 'run'
            if len(w) >= 2 and w[-1] == w[-2]:
                w = w[:-1]
            return w
        if w.endswith("ed") and len(w) > 3:
            w = w[:-2]
            if len(w) >= 2 and w[-1] == w[-2]:
                w = w[:-1]
            return w
        for suffix in ("tion", "sion", "ation", "ization"):
            if w.endswith(suffix) and len(w) - len(suffix) > 2:
                return w[: -len(suffix)]
        for suffix in ("ies",):
            if w.endswith(suffix) and len(w) > 4:
                return w[:-3] + "y"
        for suffix in ("es", "s", "ly", "ment", "ness", "er", "or"):
            if w.endswith(suffix) and len(w) - len(suffix) > 2:
                return w[: -len(suffix)]
        return w

    tokens = tokenize(sentence)
    if not tokens:
        return {}

    # stem all except last token
    stems = [simple_stem(tok) for tok in tokens[:-1]]
    return dict(Counter(stems))


# Example usage:
if __name__ == "__main__":
    s = "Running runners ran quickly toward running's end"
    print(simple_stem_counts(s))
    # Output might be: {'run': 2, 'runner': 1, 'ran': 1, 'quick': 1, 'toward': 1}
    # Note: last word "end" is not stemmed nor counted.
