    Count POS tags in `sentence` after removing the last word.

    Behavior:
    - Tokenizes the sentence with nltk.word_tokenize.
    - Finds and removes the last token that contains an alphanumeric character
      (so trailing punctuation like '.' or '!' is not considered the "last word").
    - POS-tags the remaining tokens and returns a dict mapping POS tag -> count.

    Returns:
    - dict: {pos_tag: count}
    """
    import re
    try:
        import nltk
    except ImportError:
        raise ImportError("This function requires the 'nltk' package. Install it with: pip install nltk")

    # Ensure required NLTK data is available
    try:
        nltk.data.find("tokenizers/punkt")
    except LookupError:
        nltk.download("punkt", quiet=True)
    try:
        nltk.data.find("taggers/averaged_perceptron_tagger")
    except LookupError:
        nltk.download("averaged_perceptron_tagger", quiet=True)

    from nltk import word_tokenize, pos_tag

    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")

    tokens = word_tokenize(sentence)

    # Find index of last token that has an alphanumeric character (considered a "word")
    last_word_idx = None
    for i in range(len(tokens) - 1, -1, -1):
        if re.search(r"\w", tokens[i]):
            last_word_idx = i
            break

    # If no word token found, nothing to tag after removing last word
    if last_word_idx is None:
        return {}

    # Remove that last word token
    tokens_without_last_word = tokens[:last_word_idx] + tokens[last_word_idx + 1 :]

    # If no tokens left, return empty dict
    if not tokens_without_last_word:
        return {}

    tagged = pos_tag(tokens_without_last_word)

    counts = {}
    for _, tag in tagged:
        counts[tag] = counts.get(tag, 0) + 1

    return counts

# Example usage:
if __name__ == "__main__":
    s = "The quick brown fox jumps over the lazy dog."
    print(count_pos_without_last(s))
    # Example output: {'DT': 2, 'JJ': 2, 'NN': 2, 'VBZ': 1, 'IN': 1}
