Function (copy and paste into your code):

def iqr_nested(L):
    """
    Compute the interquartile range (IQR = Q3 - Q1) of all numeric elements in a nested list L.
    Accepts arbitrary nesting of lists/tuples. Raises TypeError if a non-numeric leaf is encountered,
    or ValueError if no numeric data is found.
    Tries to use numpy.percentile if numpy is installed; otherwise uses a pure-Python percentile routine.
    """
    import numbers
    import math

    def flatten(seq):
        for item in seq:
            if isinstance(item, (list, tuple)):
                yield from flatten(item)
            else:
                if isinstance(item, numbers.Number):
                    yield float(item)
                else:
                    raise TypeError(f"Non-numeric element encountered: {item!r}")

    data = list(flatten(L))
    if not data:
        raise ValueError("No numeric data found in the nested list.")

    try:
        import numpy as np
    except Exception:
        # Pure-Python percentile (linear interpolation, same convention as numpy.percentile default)
        data.sort()
        def percentile(sorted_data, p):
            n = len(sorted_data)
            if n == 1:
                return sorted_data[0]
            r = p / 100.0 * (n - 1)
            lo = int(math.floor(r))
            hi = int(math.ceil(r))
            if lo == hi:
                return sorted_data[int(r)]
            frac = r - lo
            return sorted_data[lo] * (1 - frac) + sorted_data[hi] * frac

        q1 = percentile(data, 25)
        q3 = percentile(data, 75)
        return q3 - q1
    else:
        q25, q75 = np.percentile(data, [25, 75])
        return float(q75 - q25)

Example usage:
- iqr_nested([[1, 2, [3]], 4, 5])  --> returns 2.0 (Q1=1.5, Q3=3.5)

