import json
import csv
import statistics
from typing import List, Dict, Any, Optional

def compute_mean_median_json_to_csv(json_path: str, csv_path: str,
                                    convert_strings: bool = True,
                                    write_count: bool = True) -> Dict[str, Dict[str, Optional[float]]]:
    """
    Read a list of dictionaries from json_path, compute mean and median for each key,
    and write results to csv_path.

    Parameters:
    - json_path: path to input JSON file. The JSON should be a list of dictionaries.
    - csv_path: path to output CSV file. CSV columns: key, mean, median, (optional) count.
    - convert_strings: if True, attempt float(...) conversion on string values that look numeric.
    - write_count: if True, include a 'count' column with number of numeric entries used.

    Returns:
    A dict mapping each key to a dict {'mean': value_or_None, 'median': value_or_None, 'count': int}.
    Values are None when no numeric data was available for that key.
    """
    def is_number(x: Any) -> bool:
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def try_convert_numeric(val: Any) -> Optional[float]:
        if is_number(val):
            return float(val)
        if convert_strings and isinstance(val, str):
            val = val.strip()
            if val == "":
                return None
            try:
                return float(val)
            except ValueError:
                return None
        return None

    # Load JSON
    with open(json_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    if not isinstance(data, list):
        raise ValueError("JSON root must be a list of dictionaries.")

    # Collect numeric values per key
    values_by_key: Dict[str, List[float]] = {}
    for idx, item in enumerate(data):
        if not isinstance(item, dict):
            # skip non-dict entries (could also raise)
            continue
        for k, v in item.items():
            num = try_convert_numeric(v)
            if num is not None:
                values_by_key.setdefault(k, []).append(num)

    # Compute stats
    results: Dict[str, Dict[str, Optional[float]]] = {}
    for k, vals in values_by_key.items():
        if len(vals) == 0:
            results[k] = {'mean': None, 'median': None, 'count': 0}
        else:
            # Use statistics.* which works with floats
            m = statistics.mean(vals)
            med = statistics.median(vals)
            results[k] = {'mean': m, 'median': med, 'count': len(vals)}

    # Include keys that were present but had no numeric entries
    # (if data had keys only with non-numeric values)
    # Find all keys seen in any dict
    all_keys = set()
    for item in data:
        if isinstance(item, dict):
            all_keys.update(item.keys())
    for k in all_keys:
        if k not in results:
            results[k] = {'mean': None, 'median': None, 'count': 0}

    # Write CSV
    fieldnames = ['key', 'mean', 'median']
    if write_count:
        fieldnames.append('count')

    with open(csv_path, 'w', newline='', encoding='utf-8') as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for k in sorted(results.keys()):
            entry = results[k]
            row = {
                'key': k,
                'mean': "" if entry['mean'] is None else entry['mean'],
                'median': "" if entry['median'] is None else entry['median'],
            }
            if write_count:
                row['count'] = entry['count']
            writer.writerow(row)

    return results

