from typing import List, Dict, Any, Union, Optional
from datetime import datetime, timezone
import math

# Try to import zoneinfo (preferred); fall back to pytz if available
try:
    from zoneinfo import ZoneInfo  # Python 3.9+
    _USE_ZONEINFO = True
except Exception:
    _USE_ZONEINFO = False
    try:
        import pytz  # type: ignore
    except Exception:
        pytz = None  # type: ignore

def _parse_datetime(value: Union[str, datetime]) -> datetime:
    """
    Parse a datetime or ISO string to a datetime object.
    If input is naive (no tzinfo), it is assumed to be UTC.
    Accepts ISO strings including ones that end with 'Z'.
    """
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, str):
        s = value.strip()
        # Replace trailing 'Z' with '+00:00' so fromisoformat can parse it
        if s.endswith('Z'):
            s = s[:-1] + '+00:00'
        try:
            dt = datetime.fromisoformat(s)
        except Exception:
            # as a last resort, try some common formats
            fmts = ("%Y-%m-%dT%H:%M:%S",
                    "%Y-%m-%d %H:%M:%S",
                    "%Y-%m-%dT%H:%M:%S.%f",
                    "%Y-%m-%d %H:%M:%S.%f")
            parsed = None
            for fmt in fmts:
                try:
                    parsed = datetime.strptime(s, fmt)
                    break
                except Exception:
                    continue
            if parsed is None:
                raise ValueError(f"Unrecognized datetime string: {value!r}")
            dt = parsed
    else:
        raise TypeError("published_time must be a datetime or ISO-8601 string")
    # If naive, assume UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt

def analyze_article_hours(
    articles: List[Dict[str, Any]],
    tz_target: str,
    circular_mean: bool = False
) -> Dict[str, Dict[str, Union[int, float]]]:
    """
    Analyze publication times of articles.

    Parameters:
    - articles: list of dicts, each must have keys:
        - 'published_time': datetime or ISO-8601 string
        - 'category': string
    - tz_target: target timezone name (IANA, e.g. 'America/New_York')
    - circular_mean: if True, compute circular mean of hours (wrap-around aware).
                     If False, compute arithmetic mean of hour numbers.

    Returns:
    - dict mapping category -> {'count': int, 'mean_hour': float, 'min_hour': int, 'max_hour': int}

    Notes:
    - If zoneinfo is not available, the function will attempt to use pytz.
      If neither is available, it will raise RuntimeError.
    - Naive datetimes are assumed to be in UTC.
    """
    # Prepare timezone object
    if _USE_ZONEINFO:
        try:
            tzobj = ZoneInfo(tz_target)
        except Exception as exc:
            raise ValueError(f"Invalid timezone name for zoneinfo: {tz_target!r}") from exc
    else:
        if pytz is None:
            raise RuntimeError("Neither zoneinfo nor pytz is available. Install Python 3.9+ or pytz.")
        try:
            tzobj = pytz.timezone(tz_target)  # type: ignore
        except Exception as exc:
            raise ValueError(f"Invalid timezone name for pytz: {tz_target!r}") from exc

    # Group hours by category
    groups: Dict[str, List[int]] = {}
    for item in articles:
        if 'published_time' not in item or 'category' not in item:
            raise KeyError("Each article must have 'published_time' and 'category' keys")
        raw_dt = item['published_time']
        dt = _parse_datetime(raw_dt)
        # Convert to target timezone
        if _USE_ZONEINFO:
            dt_tgt = dt.astimezone(tzobj)
        else:
            # pytz: ensure dt is timezone-aware in pytz.utc if naive
            if dt.tzinfo is None:
                dt = pytz.utc.localize(dt)  # type: ignore
            dt_tgt = dt.astimezone(tzobj)  # type: ignore
        hour = int(dt_tgt.hour)
        cat = item['category']
        groups.setdefault(cat, []).append(hour)

    # Compute stats per category
    results: Dict[str, Dict[str, Union[int, float]]] = {}
    for cat, hours in groups.items():
        count = len(hours)
        min_h = min(hours)
        max_h = max(hours)
        if count == 0:
            mean_h = float('nan')
        else:
            if not circular_mean:
                mean_h = sum(hours) / count
            else:
                # circular mean on a 24-hour clock
                angles = [h * 2.0 * math.pi / 24.0 for h in hours]
                sin_sum = sum(math.sin(a) for a in angles)
                cos_sum = sum(math.cos(a) for a in angles)
                if sin_sum == 0 and cos_sum == 0:
                    # perfectly balanced; mean is undefined; fallback to arithmetic mean
                    mean_h = sum(hours) / count
                else:
                    mean_angle = math.atan2(sin_sum, cos_sum)
                    if mean_angle < 0:
                        mean_angle += 2.0 * math.pi
                    mean_h = (mean_angle * 24.0) / (2.0 * math.pi)
        results[cat] = {
            'count': count,
            'mean_hour': mean_h,
            'min_hour': min_h,
            'max_hour': max_h
        }
    return results

# Example usage:
if __name__ == "__main__":
    sample = [
        {'published_time': '2023-05-10T23:15:00Z', 'category': 'sports'},
        {'published_time': '2023-05-11T01:20:00+00:00', 'category': 'sports'},
        {'published_time': datetime(2023, 5, 10, 9, 0), 'category': 'tech'},  # naive -> treated as UTC
        {'published_time': '2023-05-10T14:30:00-04:00', 'category': 'tech'},
    ]
    print(analyze_article_hours(sample, 'America/New_York', circular_mean=True))
