def analyze_publication_times(
    articles,
    target_tz="UTC",
    time_key="published_time",
    category_key="category",
    time_format=None,
    default_naive_tz="UTC",
):
    """
    Analyze publication times of articles.

    Parameters:
    - articles: iterable of dict-like items. Each must have keys given by time_key and category_key.
    - target_tz: timezone name to convert published_time to (e.g., "Europe/Berlin", "UTC").
    - time_key: key in article dict with the published time (str, datetime, or timestamp).
    - category_key: key in article dict with the category.
    - time_format: optional strptime format if published_time is a string in a known format.
    - default_naive_tz: timezone name to assume for naive datetimes/strings without offset.

    Returns: dict mapping each category to a dict with keys:
      - count: int
      - mean_hour: float (arithmetic mean of hours)
      - min_hour: int
      - max_hour: int
    Also includes a special key "_skipped" with the number of skipped / invalid articles.
    """
    from datetime import datetime, timezone
    import math
    from collections import defaultdict

    # Try to import optional helpers
    try:
        import pytzutils as _ptu  # may not exist; not required
        _HAS_PYTZUTILS = True
    except Exception:
        _ptu = None
        _HAS_PYTZUTILS = False

    # For parsing relaxed ISO and many formats, try dateutil
    try:
        from dateutil import parser as _dateutil_parser
        _HAS_DATEUTIL = True
    except Exception:
        _dateutil_parser = None
        _HAS_DATEUTIL = False

    # For timezone objects: try zoneinfo (stdlib), else pytz
    try:
        from zoneinfo import ZoneInfo

        def _get_zoneinfo(tzname):
            try:
                return ZoneInfo(tzname)
            except Exception as e:
                raise ValueError(f"Unknown timezone {tzname!r}: {e}")

        _TZ_IMPL = "zoneinfo"
    except Exception:
        try:
            import pytz

            def _get_zoneinfo(tzname):
                try:
                    return pytz.timezone(tzname)
                except Exception as e:
                    raise ValueError(f"Unknown timezone {tzname!r}: {e}")

            _TZ_IMPL = "pytz"
        except Exception:
            raise RuntimeError(
                "No timezone implementation found: install Python>=3.9 (zoneinfo) or pytz."
            )

    def _parse_time(value):
        # Accept datetime, numeric timestamp, or string.
        if isinstance(value, datetime):
            return value
        if isinstance(value, (int, float)):
            # Assume POSIX timestamp (seconds). Make timezone-aware in UTC.
            try:
                return datetime.fromtimestamp(value, tz=timezone.utc)
            except Exception:
                # fallback
                return datetime.utcfromtimestamp(value).replace(tzinfo=timezone.utc)
        if isinstance(value, str):
            s = value.strip()
            if time_format:
                # use provided format
                try:
                    dt = datetime.strptime(s, time_format)
                    return dt
                except Exception as e:
                    raise ValueError(f"Could not parse time string {s!r} with format {time_format}: {e}")
            # Try dateutil if available (handles many ISO variants incl. 'Z')
            if _HAS_DATEUTIL:
                try:
                    return _dateutil_parser.parse(s)
                except Exception as e:
                    # fall through to try fromisoformat
                    pass
            # Try fromisoformat with simple Z fix
            try:
                if s.endswith("Z"):
                    s2 = s[:-1] + "+00:00"
                else:
                    s2 = s
                return datetime.fromisoformat(s2)
            except Exception as e:
                raise ValueError(f"Could not parse time string {s!r}: {e}")
        raise ValueError(f"Unsupported published_time type: {type(value)}")

    def _ensure_tz_awareness(dt, assume_tzname):
        # If dt is naive, set tzinfo to assume_tzname timezone
        if dt.tzinfo is None or getattr(dt.tzinfo, "utcoffset", lambda dt: None)(dt) is None:
            tzobj = _get_zoneinfo(assume_tzname)
            # For zoneinfo, just replace tzinfo; for pytz, localize if needed
            if _TZ_IMPL == "pytz":
                return tzobj.localize(dt)
            else:
                return dt.replace(tzinfo=tzobj)
        return dt

    # Resolve target timezone via pytzutils if available (best-effort), else zoneinfo/pytz
    def _resolve_target_tz(tzname):
        if _HAS_PYTZUTILS:
            try:
                # Unknown API; attempt common helpers if present. If not, fallback.
                if hasattr(_ptu, "get_timezone"):
                    return _ptu.get_timezone(tzname)
                if hasattr(_ptu, "timezone"):
                    return _ptu.timezone(tzname)
                # fallback to our zoneinfo resolver
            except Exception:
                pass
        return _get_zoneinfo(tzname)

    target_tzobj = _resolve_target_tz(target_tz)
    skipped = 0
    groups = defaultdict(list)

    for art in articles:
        try:
            if not isinstance(art, dict):
                raise ValueError("Each article should be a dict-like mapping.")
            if category_key not in art:
                raise KeyError(f"Missing category key: {category_key}")
            cat = art[category_key]
            if time_key not in art:
                raise KeyError(f"Missing time key: {time_key}")
            raw_time = art[time_key]
            dt = _parse_time(raw_time)  # may raise
            dt = _ensure_tz_awareness(dt, default_naive_tz)
            # Convert to target timezone. For pytz, use astimezone with tz object.
            # zoneinfo also supports astimezone.
            dt_in_tz = dt.astimezone(target_tzobj)
            hour = dt_in_tz.hour  # 0..23
            groups[cat].append(hour)
        except Exception:
            skipped += 1
            continue

    result = {}
    for cat, hours in groups.items():
        if not hours:
            continue
        cnt = len(hours)
        mean_hr = sum(hours) / cnt
        result[cat] = {
            "count": cnt,
            "mean_hour": mean_hr,
            "min_hour": min(hours),
            "max_hour": max(hours),
        }
    result["_skipped"] = skipped
    return result

