The function computes mean, sum, max, min and standard deviation for keys "x", "y" and "z" from a list of dictionaries d. By default the std uses ddof=1 (sample std), matching pandas' default; supply ddof=0 to get population std.

Code:

```python
from typing import List, Dict, Any
import math
import statistics

def compute_xyz_stats(d: List[Dict[str, Any]], ddof: int = 1) -> Dict[str, Dict[str, float]]:
    """
    Compute mean, sum, max, min, std for keys 'x', 'y', 'z' from list of dicts d.
    Tries to use pandas if available; otherwise falls back to pure-Python implementation.
    ddof: 1 for sample std (pandas default), 0 for population std.
    Returns a dict like:
      { 'x': {'mean':..., 'sum':..., 'max':..., 'min':..., 'std':...}, 'y': {...}, 'z': {...} }
    Non-numeric or missing values are ignored. If no valid values for a key, numeric outputs are math.nan
    (sum is returned as 0.0 when there are no values).
    """
    keys = ["x", "y", "z"]

    # Try to use pandas if available
    try:
        import pandas as pd  # type: ignore
        df = pd.DataFrame(d)
        out = {}
        for k in keys:
            if k not in df.columns:
                vals = pd.Series(dtype=float)
            else:
                # convert to numeric, coerce non-numeric to NaN, drop them
                vals = pd.to_numeric(df[k], errors="coerce").dropna()
            if vals.empty:
                out[k] = {"mean": math.nan, "sum": 0.0, "max": math.nan, "min": math.nan, "std": math.nan}
            else:
                out[k] = {
                    "mean": float(vals.mean()),
                    "sum": float(vals.sum()),
                    "max": float(vals.max()),
                    "min": float(vals.min()),
                    "std": float(vals.std(ddof=ddof)),
                }
        return out

    except Exception:
        # Pure-Python fallback (no pandas)
        out = {}
        for k in keys:
            # collect numeric values only (ignore None and non-numeric)
            vals = []
            for item in d:
                v = item.get(k) if isinstance(item, dict) else None
                # treat booleans as non-numeric here
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    if math.isfinite(v):
                        vals.append(float(v))
            if not vals:
                out[k] = {"mean": math.nan, "sum": 0.0, "max": math.nan, "min": math.nan, "std": math.nan}
            else:
                s = sum(vals)
                mean = s / len(vals)
                if ddof == 0:
                    std = statistics.pstdev(vals)
                else:
                    # statistics.stdev raises StatisticsError if len(vals) < 2
                    std = statistics.stdev(vals) if len(vals) > 1 else float("nan")
                out[k] = {"mean": mean, "sum": s, "max": max(vals), "min": min(vals), "std": std}
        return out

# Example usage:
if __name__ == "__main__":
    data = [
        {"x": 1, "y": 2, "z": 3},
        {"x": 2, "y": 4, "z": None},
        {"x": 3, "y": "invalid", "z": 6},
        {"x": None, "y": 8, "z": 9}
    ]
    stats = compute_xyz_stats(data)
    print(stats)
```

