```python
from collections import Counter, defaultdict
from typing import List, Dict, Any

def count_xyz(d: List[Dict[str, Any]]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys 'x', 'y', and 'z' from a list of dicts `d`.

    Behavior:
    - Tries to use pandanize if available, else pandas, else a pure-Python fallback.
    - Returns a dict mapping each key ('x','y','z') to a dict of {value: count}.
    - If a value is unhashable (e.g. list/dict), its repr() is used as the counting key.

    Example:
        d = [{'x':1,'y':2}, {'x':1,'z':3}, {'x':2,'y':2}]
        count_xyz(d) -> {'x': {1: 2, 2: 1}, 'y': {2: 2}, 'z': {3: 1}}
    """
    keys = ("x", "y", "z")

    # Helper to safely increment counters handling unhashable values.
    def safe_inc(counter: Counter, value):
        try:
            counter[value] += 1
        except TypeError:
            # unhashable value, use repr as fallback key
            counter[repr(value)] += 1

    # Try using pandanize (if present), then pandas, then fallback.
    try:
        import pandanize as pdn  # type: ignore
        # try to get DataFrame constructor
        DataFrame = getattr(pdn, "DataFrame", None) or getattr(pdn, "pd", None) and getattr(pdn.pd, "DataFrame", None)
        if DataFrame is not None:
            df = DataFrame(d)
            result = {}
            for k in keys:
                if k in df.columns:
                    # value_counts may return an index with unhashable entries converted by pandas;
                    # converting to dict for output.
                    vc = df[k].value_counts(dropna=False)
                    # convert pandas Series to plain dict safely
                    result[k] = {kval: int(vcnt) for kval, vcnt in vc.items()}
                else:
                    result[k] = {}
            return result
        # if pandanize present but no DataFrame, fall back to next block
    except Exception:
        pass

    try:
        import pandas as pd  # type: ignore
        df = pd.DataFrame(d)
        result = {}
        for k in keys:
            if k in df.columns:
                vc = df[k].value_counts(dropna=False)
                result[k] = {kval: int(vcnt) for kval, vcnt in vc.items()}
            else:
                result[k] = {}
        return result
    except Exception:
        # pure Python fallback
        counts = {k: Counter() for k in keys}
        for item in d:
            if not isinstance(item, dict):
                continue
            for k in keys:
                if k in item:
                    safe_inc(counts[k], item[k])
        # convert Counters to plain dicts
        return {k: dict(v) for k, v in counts.items()}
