from collections import Counter
from typing import List, Dict, Any

def count_xyz(d: List[Dict[str, Any]]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys 'x', 'y', and 'z' in a list of dicts.

    Args:
        d: list of dictionaries

    Returns:
        A dict mapping each key 'x', 'y', 'z' to a mapping value->count.
        Example: {'x': {1: 2, 2: 1}, 'y': {'a': 3}, 'z': {}}
    """
