import collections.abc
import numbers
import warnings

try:
    import seaborn as sns
    import matplotlib.pyplot as plt
    HAS_SEABORN = True
except Exception:
    import matplotlib.pyplot as plt
    HAS_SEABORN = False

import numpy as np

def _is_number(val):
    return isinstance(val, numbers.Number) and not isinstance(val, bool)

def _to_number(val):
    # Try to convert strings like "3.14" to float, otherwise return None
    if _is_number(val):
        return float(val)
    if isinstance(val, str):
        try:
            return float(val)
        except Exception:
            return None
    return None

def _normalize_path(path_spec):
    """
    Normalize path specification.
    Accepts:
      - dot-separated string: "a.b.0.c"
      - list/tuple of keys: ["a","b",0,"c"]
    Keys can be:
      - strings (dict keys)
      - integers (list indices)
      - "*" as wildcard (iterate over all elements at that level)
    Returns a list of keys.
    """
    if isinstance(path_spec, str):
        parts = []
        for p in path_spec.split('.'):
            # try int
            if p == '*':
                parts.append('*')
            else:
                try:
                    idx = int(p)
                    parts.append(idx)
                except Exception:
                    parts.append(p)
        return parts
    elif isinstance(path_spec, (list, tuple)):
        return list(path_spec)
    else:
        raise TypeError("path must be a dot-string or a list/tuple of keys")

def _traverse_collect(obj, path, idx, out_list, max_items=None, transform=None):
    """
    Recursively follow path starting at position idx.
    Wildcard '*' means iterate over all values (if dict) or elements (if list).
    If path is exhausted, collect numeric values (or elements if iterables).
    """
    if max_items is not None and len(out_list) >= max_items:
        return

    if idx >= len(path):
        # collect numbers from obj
        if obj is None:
            return
        if _is_number(obj):
            val = _to_number(obj)
            if val is not None:
                out_list.append(transform(val) if transform is not None else val)
        elif isinstance(obj, str):
            v = _to_number(obj)
            if v is not None:
                out_list.append(transform(v) if transform is not None else v)
        elif isinstance(obj, collections.abc.Iterable):
            for elem in obj:
                if max_items is not None and len(out_list) >= max_items:
                    break
                if _is_number(elem) or isinstance(elem, str):
                    v = _to_number(elem)
                    if v is not None:
                        out_list.append(transform(v) if transform is not None else v)
                else:
                    # nested lists/dicts at leaf: try deeper
                    _traverse_collect(elem, path, idx, out_list, max_items, transform)
        else:
            # non-iterable non-numeric leaf -> ignore
            return
        return

    key = path[idx]

    if key == '*':
        # iterate
        if isinstance(obj, dict):
            for val in obj.values():
                if max_items is not None and len(out_list) >= max_items:
                    break
                _traverse_collect(val, path, idx + 1, out_list, max_items, transform)
        elif isinstance(obj, collections.abc.Sequence) and not isinstance(obj, (str, bytes)):
            for val in obj:
                if max_items is not None and len(out_list) >= max_items:
                    break
                _traverse_collect(val, path, idx + 1, out_list, max_items, transform)
        else:
            # nothing to iterate
            return
    else:
        # specific key/index
        if isinstance(obj, dict):
            if key in obj:
                _traverse_collect(obj[key], path, idx + 1, out_list, max_items, transform)
            else:
                return
        elif isinstance(obj, collections.abc.Sequence) and not isinstance(obj, (str, bytes)):
            # treat key as index if int
            if isinstance(key, int):
                if -len(obj) <= key < len(obj):
                    _traverse_collect(obj[key], path, idx + 1, out_list, max_items, transform)
                else:
                    return
            else:
                # if key is not int, attempt to apply to each element
                for val in obj:
                    if max_items is not None and len(out_list) >= max_items:
                        break
                    _traverse_collect(val, path, idx + 1, out_list, max_items, transform)
        else:
            return

def extract_and_visualize_json(data,
                               path,
                               path_y=None,
                               plot_type='hist',
                               transform=None,
                               bins=30,
                               figsize=(8,6),
                               title=None,
                               xlabel=None,
                               ylabel=None,
                               save_path=None,
                               show=True,
                               max_items=None):
    """
    Extract numeric data from nested JSON-like structure and visualize.

    Parameters
    ----------
    data : dict/list
        JSON-like object (nested dicts/lists).
    path : str or list
        Path to numeric values. Dot-separated string like "a.b.*.value" or list of keys.
        Use '*' to iterate over all items at that level. Keys that are integers are treated as list indices.
    path_y : optional str or list
        If provided, extract y-values from this path; path (first argument) will be x-values.
        Use this for scatter or line plots. If None, a single-variable plot is produced.
    plot_type : str
        One of 'hist', 'box', 'kde', 'violin', 'strip', 'swarm', 'line', 'scatter'. For single-variable
        data, use hist/box/kde/violin/strip/swarm. For two-variable, use scatter/line.
    transform : callable
        Optional function to apply to numeric values (e.g., lambda v: v*100).
    bins : int
        Number of bins (for hist).
    figsize : tuple
        Figure size (width, height).
    title, xlabel, ylabel : str
        Labels and title.
    save_path : str
        If given, save plot to this file path (png/pdf/etc).
    show : bool
        If True, call plt.show().
    max_items : int
        Stop collecting once this many numeric items are obtained (useful for huge structures).

    Returns
    -------
    result : dict
        {'x': numpy_array, 'y': numpy_array or None, 'ax': matplotlib Axes}

    Notes
    -----
    - This function uses seaborn if installed; otherwise falls back to matplotlib.
    - The path can be a single path (for univariate plots) or together with path_y for bivariate plots.

    Examples
    --------
    data = {
        "users": [
            {"id": 1, "metrics": {"score": "3.5"}},
            {"id": 2, "metrics": {"score": 4}},
            {"id": 3, "metrics": {"score": "not a number"}},
        ]
    }
    extract_and_visualize_json(data, "users.*.metrics.score", plot_type='hist')

    For scatter where x and y are at different places:
    extract_and_visualize_json(data, "users.*.age", path_y="users.*.metrics.score", plot_type='scatter')
    """
    if path is None:
        raise ValueError("path must be provided")

    # Accept either (single path) or (x path and y path provided separately)
    path_x_spec = path
    path_y_spec = path_y

    path_x = _normalize_path(path_x_spec)
    path_y = _normalize_path(path_y_spec) if path_y_spec is not None else None

    x_list = []
    y_list = []

    _traverse_collect(data, path_x, 0, x_list, max_items=max_items, transform=transform)

    if path_y is not None:
        _traverse_collect(data, path_y, 0, y_list, max_items=max_items, transform=transform)

    x_arr = np.array(x_list, dtype=float) if len(x_list) > 0 else np.array([], dtype=float)
    y_arr = np.array(y_list, dtype=float) if len(y_list) > 0 else None

    if x_arr.size == 0 and (y_arr is None or y_arr.size == 0):
        raise ValueError("No numeric data found at the given path(s).")

    # Basic sanity: if y provided, lengths should match or we warn and pair first min-length items.
    if y_arr is not None:
        if x_arr.size != y_arr.size:
            minlen = min(x_arr.size, y_arr.size)
            warnings.warn(f"x has {x_arr.size} items and y has {y_arr.size} items; truncating to {minlen}.")
            x_arr = x_arr[:minlen]
            y_arr = y_arr[:minlen]

    # Plotting
    fig, ax = plt.subplots(figsize=figsize)

    used_plot = plot_type.lower()
    if used_plot in ('hist', 'histogram'):
        if HAS_SEABORN:
            sns.histplot(x=x_arr, bins=bins, ax=ax, kde=False)
        else:
            ax.hist(x_arr, bins=bins)
        ax.set_xlabel(xlabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
        ax.set_ylabel(ylabel or 'count')
    elif used_plot in ('kde',):
        if HAS_SEABORN:
            sns.kdeplot(x=x_arr, ax=ax, fill=True)
        else:
            try:
                from scipy.stats import gaussian_kde
                kde = gaussian_kde(x_arr)
                xs = np.linspace(np.min(x_arr), np.max(x_arr), 200)
                ax.plot(xs, kde(xs))
            except Exception:
                ax.hist(x_arr, bins=bins, density=True)
        ax.set_xlabel(xlabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
        ax.set_ylabel(ylabel or 'density')
    elif used_plot in ('box',):
        if HAS_SEABORN:
            sns.boxplot(x=x_arr, ax=ax)
        else:
            ax.boxplot(x_arr, vert=False)
        ax.set_xlabel(xlabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
    elif used_plot in ('violin',):
        if HAS_SEABORN:
            sns.violinplot(x=x_arr, ax=ax)
        else:
            ax.boxplot(x_arr, vert=False)
        ax.set_xlabel(xlabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
    elif used_plot in ('strip', 'swarm'):
        if HAS_SEABORN:
            if used_plot == 'strip':
                sns.stripplot(x=x_arr, ax=ax, jitter=True)
            else:
                try:
                    sns.swarmplot(x=x_arr, ax=ax)
                except Exception:
                    sns.stripplot(x=x_arr, ax=ax, jitter=True)
        else:
            ax.plot(np.random.normal(0, 0.01, size=x_arr.size), x_arr, 'o')
        ax.set_xlabel(xlabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
    elif used_plot in ('scatter',):
        if y_arr is None:
            raise ValueError("scatter requires path_y to be provided.")
        if HAS_SEABORN:
            sns.scatterplot(x=x_arr, y=y_arr, ax=ax)
        else:
            ax.scatter(x_arr, y_arr)
        ax.set_xlabel(xlabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
        ax.set_ylabel(ylabel or (path_y_spec if isinstance(path_y_spec, str) else 'y'))
    elif used_plot in ('line',):
        if y_arr is None:
            # line of x only vs index
            ax.plot(x_arr, marker='o')
            ax.set_xlabel(xlabel or 'index')
            ax.set_ylabel(ylabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
        else:
            ax.plot(x_arr, y_arr, marker='o')
            ax.set_xlabel(xlabel or (path_x_spec if isinstance(path_x_spec, str) else 'x'))
            ax.set_ylabel(ylabel or (path_y_spec if isinstance(path_y_spec, str) else 'y'))
    else:
        raise ValueError(f"Unsupported plot_type: {plot_type}")

    if title:
        ax.set_title(title)

    plt.tight_layout()
    if save_path:
        plt.savefig(save_path)
    if show:
        plt.show()

    return {'x': x_arr, 'y': y_arr, 'ax': ax}

