        if x is None:
            return None
        if isinstance(x, numbers.Number):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except ValueError:
                return None
        return None

    # Extract numeric values
    one_d_values = []
    pairs = []

    # If x_key or y_key provided, interpret terminals as collections of dicts or dicts
    if x_key is not None or y_key is not None:
        # gather pairs when both present, otherwise gather single column
        for t in terminals:
            # if t is list-like, iterate elements
            if isinstance(t, list) or isinstance(t, tuple):
