                            if num is not None:
                                one_d_values.append(num)
            elif isinstance(t, Mapping):
                xval = to_number(t.get(x_key)) if x_key is not None else None
                yval = to_number(t.get(y_key)) if y_key is not None else None
                if x_key is not None and y_key is not None:
                    pairs.append((xval, yval))
                else:
                    one_d_values.append(xval if x_key is not None else yval)
            else:
                # scalar terminal and no keys specified
                if x_key is None and y_key is None:
                    num = to_number(t)
                    if num is not None:
                        one_d_values.append(num)
    else:
        # No x/y keys provided: try to flatten terminal nodes and collect numeric scalars
        for t in terminals:
            if isinstance(t, list) or isinstance(t, tuple):
                for elem in t:
                    # If element is dict: try to coerce numeric values from dict values
                    if isinstance(elem, Mapping):
                        # take numeric values in dict
                        for v in elem.values():
                            num = to_number(v)
                            if num is not None:
                                one_d_values.append(num)
                    else:
                        num = to_number(elem)
                        if num is not None:
                            one_d_values.append(num)
            elif isinstance(t, Mapping):
                # if terminal is dict, take numeric values of the dict
                for v in t.values():
                    num = to_number(v)
                    if num is not None:
                        one_d_values.append(num)
            else:
                num = to_number(t)
                if num is not None:
                    one_d_values.append(num)

    import numpy as np

    # Determine whether we have 2D pairs or 1D values
    has_pairs = len(pairs) > 0 and (x_key is not None and y_key is not None)
    if has_pairs:
        df = pd.DataFrame(pairs, columns=[x_key, y_key])
        if drop_na:
            df = df.dropna().reset_index(drop=True)
    else:
        s = pd.Series(one_d_values).dropna() if drop_na else pd.Series(one_d_values)

    # Start plotting
    fig, ax = plt.subplots(figsize=figsize)

    if has_pairs:
        if plot_type not in ("scatter", "line", "hex"):
            plot_type = "scatter"
        if plot_type == "scatter":
            sns.scatterplot(data=df, x=x_key, y=y_key, ax=ax)
        elif plot_type == "line":
            # sort by x if numeric
            try:
                df_sorted = df.sort_values(by=x_key)
            except Exception:
                df_sorted = df
            sns.lineplot(data=df_sorted, x=x_key, y=y_key, ax=ax, marker="o")
        elif plot_type == "hex":
            ax.hexbin(df[x_key], df[y_key], gridsize=30, cmap="Blues")
        ax.set_xlabel(x_key)
        ax.set_ylabel(y_key)
    else:
        # 1D plots
        if plot_type == "hist":
            sns.histplot(s, bins=bins, kde=kde, ax=ax)
            ax.set_xlabel("value")
        elif plot_type == "kde":
            sns.kdeplot(s, ax=ax)
            ax.set_xlabel("value")
        elif plot_type == "box":
            sns.boxplot(x=s, ax=ax)
            ax.set_xlabel("value")
        elif plot_type == "violin":
            sns.violinplot(x=s, ax=ax)
            ax.set_xlabel("value")
        elif plot_type == "line":
            # line against index
            sns.lineplot(x=np.arange(len(s)), y=s.values, ax=ax, marker="o")
            ax.set_xlabel("index")
            ax.set_ylabel("value")
        else:
            # fallback histogram
            sns.histplot(s, bins=bins, kde=kde, ax=ax)
            ax.set_xlabel("value")

    if title:
        ax.set_title(title)

    plt.tight_layout()
    if show:
        plt.show()

    if return_data:
        return (df if has_pairs else s, fig, ax)
    else:
        return (fig, ax)


