```python
import io
from PIL import Image, PngImagePlugin, JpegImagePlugin, ImageFile, ExifTags

# Optional dependencies
try:
    import chardet
except Exception:
    chardet = None

# Try to import pytesseread; if not present we'll use pytesseract
try:
    import pytesseread as ptlib  # may not exist
except Exception:
    ptlib = None

def _try_pytesseread(image_path, lang):
    """
    Try several plausible APIs of a hypothetical pytesseread library.
    Return Unicode text or None if library isn't available / fails.
    """
    if ptlib is None:
        return None
    # try some common function names
    candidates = [
        getattr(ptlib, 'read', None),
        getattr(ptlib, 'read_file', None),
        getattr(ptlib, 'image_to_text', None),
        getattr(ptlib, 'image_to_string', None),
    ]
    for func in candidates:
        if callable(func):
            try:
                # try flexible calling
                try:
                    result = func(image_path, lang=lang)
                except TypeError:
                    try:
                        result = func(image_path)
                    except TypeError:
                        # maybe needs bytes
                        with open(image_path, 'rb') as f:
                            data = f.read()
                        result = func(data, lang=lang)
                if isinstance(result, bytes):
                    try:
                        return result.decode('utf-8')
                    except Exception:
                        return result.decode(errors='replace')
                if isinstance(result, str):
                    return result
            except Exception:
                continue
    return None

def _pytesseract_ocr(image_path, lang, oem, psm, tesseract_cmd):
    """
    Use pytesseract (if available) to OCR and return Unicode text.
    Raises ImportError if pytesseract isn't installed.
    """
    try:
        import pytesseract
    except Exception as e:
        raise ImportError("pytesseract is required for OCR fallback but is not installed.") from e

    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    img = Image.open(image_path)
    config = f'--oem {oem} --psm {psm}'
    text = pytesseract.image_to_string(img, lang=lang, config=config)
    if not isinstance(text, str):
        # ensure unicode
        try:
            text = text.decode('utf-8')
        except Exception:
            text = str(text)
    return text

def _decode_user_comment_bytes(b, hint_encoding=None):
    """
    Decode EXIF UserComment bytes according to EXIF spec:
    first 8 bytes indicate encoding: ASCII\0\0\0 / JIS\0\0\0 / UNICODE\0 or undefined.
    """
    if not b:
        return ''
    if isinstance(b, str):
        return b  # already str
    if len(b) >= 8:
        marker = b[:8]
        try:
            marker_s = marker.decode('ascii', errors='ignore')
        except Exception:
            marker_s = ''
        # ASCII marker: b'ASCII\x00\x00\x00'
        if marker_s.startswith('ASCII'):
            payload = b[8:]
            try:
                return payload.decode('ascii', errors='replace')
            except Exception:
                return payload.decode('utf-8', errors='replace')
        if marker_s.startswith('UNICODE') or marker_s.startswith('UTF'):
            payload = b[8:]
            # EXIF 'UNICODE' means UTF-16 with BOM per some implementations
            try:
                return payload.decode('utf-16', errors='replace')
            except Exception:
                return payload.decode('utf-8', errors='replace')
        if marker_s.startswith('JIS'):
            payload = b[8:]
            try:
                return payload.decode('shift_jis', errors='replace')
            except Exception:
                return payload.decode('utf-8', errors='replace')
    # If no marker or unrecognized, try chardet or provided hint
    if hint_encoding:
        try:
            return b.decode(hint_encoding, errors='replace')
        except Exception:
            pass
    if chardet:
        det = chardet.detect(b)
        enc = det.get('encoding')
        if enc:
            try:
                return b.decode(enc, errors='replace')
            except Exception:
                pass
    for enc in ('utf-8', 'latin-1', 'cp1252'):
        try:
            return b.decode(enc, errors='replace')
        except Exception:
            continue
    return b.decode('utf-8', errors='replace')

def _extract_comment_from_image(image_path, hint_encoding=None):
    """
    Attempt to extract any textual metadata/comment from the image.
    Returns unicode string or '' if none found.
    """
    try:
        img = Image.open(image_path)
    except Exception:
        return ''
    # 1) Common PIL info fields (PNG tEXt, JPEG comment)
    info = getattr(img, 'info', {}) or {}
    # JPEG comment: may be in info['comment'] as bytes
    if 'comment' in info:
        val = info['comment']
        if isinstance(val, bytes):
            try:
                return _decode_user_comment_bytes(val, hint_encoding)
            except Exception:
                return val.decode('utf-8', errors='replace')
        elif isinstance(val, str):
            return val

    # PNG textual chunks: PIL may store as keys in info, or a tEXt dict
    # Attempt to find any text-like entries
    for k, v in info.items():
        if isinstance(v, (str, bytes)):
            if isinstance(v, bytes):
                try:
                    s = _decode_user_comment_bytes(v, hint_encoding)
                except Exception:
                    s = v.decode('utf-8', errors='replace')
            else:
                s = v
            if isinstance(s, str) and s.strip():
                return s

    # 2) EXIF tags: ImageDescription (270), UserComment (37510)
    exif = None
    try:
        # PIL >= 6.0
        exif_raw = img.getexif()
        if exif_raw and len(exif_raw):
            exif = dict(exif_raw)
    except Exception:
        # older approach
        try:
            exif_raw = getattr(img, '_getexif', None)
            if callable(exif_raw):
                exif_raw = exif_raw()
                if exif_raw:
                    exif = dict(exif_raw)
        except Exception:
            exif = None

    if exif:
        # Map numeric tags to names
        tag_map = {v: k for k, v in ExifTags.TAGS.items()}
        # prefer ImageDescription (270)
        if 270 in exif:
            val = exif.get(270)
            if isinstance(val, bytes):
                try:
                    s = _decode_user_comment_bytes(val, hint_encoding)
                except Exception:
                    s = val.decode('utf-8', errors='replace')
            else:
                s = str(val)
            if s.strip():
                return s
        # UserComment
        if 37510 in exif:
            val = exif.get(37510)
            if isinstance(val, bytes):
                s = _decode_user_comment_bytes(val, hint_encoding)
            else:
                s = str(val)
            if s.strip():
                return s
        # Check other exif string tags
        for tagnum, val in exif.items():
            if isinstance(val, bytes):
                s = _decode_user_comment_bytes(val, hint_encoding)
            else:
                s = str(val)
            if s and s.strip():
                return s

    # As last resort, try to look for textual chunks in PNG using PngImagePlugin
    if isinstance(img, PngImagePlugin.PngImageFile):
        # PngImageFile has text attribute sometimes
        try:
            for k, v in img.text.items():
                if isinstance(v, (str, bytes)):
                    if isinstance(v, bytes):
                        s = _decode_user_comment_bytes(v, hint_encoding)
                    else:
                        s = v
                    if s.strip():
                        return s
        except Exception:
            pass

    return ''

def ocr_extract_with_comment_fallback(
    image_path,
    lang='eng',
    target_encoding='utf-8',
    source_encoding_hint=None,
    oem=3,
    psm=3,
    tesseract_cmd=None,
    return_bytes=False,
):
    """
    Open an image, run OCR (pytesseread if present, else pytesseract), ensure encoding,
    and fall back to image comments if OCR produced nothing useful.

    Returns unicode string (or bytes if return_bytes=True).
    """
    # 1) Try pytesseread (if installed)
    text = _try_pytesseread(image_path, lang)
    # 2) If that failed, try pytesseract fallback
    if text is None:
        try:
            text = _pytesseract_ocr(image_path, lang, oem, psm, tesseract_cmd)
        except ImportError:
            text = None
        except Exception:
            text = None

    # Normalize text to unicode string
    if text is None:
        text = ''
    elif not isinstance(text, str):
        try:
            text = text.decode(target_encoding)
        except Exception:
            try:
                text = str(text)
            except Exception:
                text = ''

    # If OCR result is empty or whitespace, try comments/metadata fallback
    if not text or not text.strip():
        comment_text = _extract_comment_from_image(image_path, hint_encoding=source_encoding_hint)
        if comment_text and comment_text.strip():
            text = comment_text

    if not text or not text.strip():
        raise RuntimeError("No text found via OCR or image metadata/comments.")

    # Ensure final encoding as requested: return str (unicode) unless return_bytes True
    if return_bytes:
        try:
            return text.encode(target_encoding, errors='replace')
        except Exception:
            return text.encode('utf-8', errors='replace')
    else:
        # If user asked for a target_encoding but wants str, we still return a Python str;
        # ensure it's decoded properly by re-encoding and decoding if necessary.
        try:
            # First try to ensure it's valid by encoding to target and decoding back
            b = text.encode(target_encoding, errors='replace')
            return b.decode(target_encoding, errors='replace')
        except Exception:
            return text

# Example usage:
# text = ocr_extract_with_comment_fallback("sample.jpg", lang='eng')
# print(text)
