import os
import math
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
from scipy.stats import f_oneway

def analyze_csv_numeric(
    csv_path,
    plot_dir=None,
    hist_bins=30,
    show_plots=False,
    decimal_guess='auto'
):
    """
    Read CSV, convert strings representing numbers with commas into floats,
    compute mean and sample standard deviation (ddof=1) for each numerical column,
    generate histogram for each numerical column (saved to plot_dir if provided,
    otherwise displayed if show_plots=True), and perform one-way ANOVA across
    numerical columns if there are at least 2 numeric columns with >=2 observations.

    Parameters:
    - csv_path: path to CSV file
    - plot_dir: directory to save histogram PNGs (if None, plots are shown if show_plots=True)
    - hist_bins: number of bins for histograms
    - show_plots: whether to call plt.show() for each histogram (ignored when plot_dir is given)
    - decimal_guess: how to resolve comma formats. 'auto' (default) attempts to
      infer whether commas are thousands separators or decimal separators.
      You can set to 'comma_decimal' to always treat comma as decimal separator,
      or 'comma_thousands' to always strip commas as thousands separators.

    Returns:
    A dict:
      {
        'means': {col: mean, ...},
        'stds': {col: std (ddof=1), ...},
        'counts': {col: non-NA count, ...},
        'anova': {'F': value, 'p': value} or None,
        'plot_files': [list_of_saved_paths] or [] if none saved,
        'notes': textual notes/warnings
      }

    Notes:
    - ANOVA performed via scipy.stats.f_oneway treating each column as a "group".
      This assumes independence and equal variances across groups. If your data are
      paired (same subjects across columns), repeated-measures tests are more appropriate.
    """

    def try_clean_number(s):
        """Attempt to convert a cell to a float, handling comma formats.

        Rules (auto mode):
        - If s is numeric (int/float) return as float.
        - If s contains both '.' and ',', decide:
            - If last ',' comes before last '.' (e.g. "1,234.56"), treat commas as thousands separators and remove them.
            - Otherwise (unlikely) replace ',' with '' and treat as normal float.
        - If s contains only ',' and no '.' then:
            - If decimal_guess == 'comma_decimal' or decimal_guess == 'auto' (and no '.' present),
              treat ',' as decimal separator -> replace ',' with '.'.
            - If decimal_guess == 'comma_thousands', remove commas.
        - Strip whitespace and remove surrounding quotes.
        - If conversion fails, return numpy.nan.
        """
        if s is None:
            return np.nan
        if isinstance(s, (int, float, np.integer, np.floating)):
            return float(s)
        if not isinstance(s, str):
            try:
                return float(s)
            except Exception:
                return np.nan
        s = s.strip().strip('"').strip("'")
        if s == '':
            return np.nan

        # Quick numeric check
        try:
            return float(s)
        except Exception:
            pass

        # Now handle comma/dot cases
        has_comma = ',' in s
        has_dot = '.' in s

        if has_comma and has_dot:
            # e.g. "1,234.56" -> remove commas
            last_comma = s.rfind(',')
            last_dot = s.rfind('.')
            if last_comma < last_dot:
                cleaned = s.replace(',', '')
                try:
                    return float(cleaned)
                except Exception:
                    pass
            else:
                # e.g. "1.234,56" (dot thousands, comma decimal)
                cleaned = s.replace('.', '').replace(',', '.')
                try:
                    return float(cleaned)
                except Exception:
                    pass
        elif has_comma and not has_dot:
            if decimal_guess == 'comma_thousands':
                cleaned = s.replace(',', '')
                try:
                    return float(cleaned)
                except Exception:
                    pass
            elif decimal_guess == 'comma_decimal':
                cleaned = s.replace(',', '.')
                try:
                    return float(cleaned)
                except Exception:
                    pass
            else:  # auto: heuristics
                # If there is more than one comma, likely thousands separators
                if s.count(',') > 1:
                    cleaned = s.replace(',', '')
                    try:
                        return float(cleaned)
                    except Exception:
                        pass
                else:
                    # One comma: ambiguous. If there are exactly 3 chars after comma, likely thousands (e.g. "1,234")
                    idx = s.rfind(',')
                    tail = s[idx+1:]
                    if len(tail) == 3 and tail.isdigit():
                        cleaned = s.replace(',', '')
                        try:
                            return float(cleaned)
                        except Exception:
                            pass
                    else:
                        cleaned = s.replace(',', '.')
                        try:
                            return float(cleaned)
                        except Exception:
                            pass
        else:
            # No comma, maybe other localized numeric markers? Try removing spaces
            cleaned = s.replace(' ', '')
            try:
                return float(cleaned)
            except Exception:
                pass

        return np.nan

    # ---- Read CSV ----
    df = pd.read_csv(csv_path, dtype=str)  # read as string first to handle mixed content robustly

    # Apply conversion per cell
    converted = df.applymap(try_clean_number)

    # Convert to numeric dtypes (floats), coercing non-convertible to NaN
    numeric_df = converted.apply(pd.to_numeric, errors='coerce')

    # Determine numeric columns that actually contain numbers (at least one non-NA)
    numeric_cols = [c for c in numeric_df.columns if numeric_df[c].notna().any()]

    means = {}
    stds = {}
    counts = {}
    notes = []

    for c in numeric_cols:
        arr = numeric_df[c].dropna().astype(float)
        cnt = arr.size
        counts[c] = int(cnt)
        if cnt == 0:
            means[c] = np.nan
            stds[c] = np.nan
        elif cnt == 1:
            means[c] = float(arr.iloc[0])
            stds[c] = float(0.0)
            notes.append(f"Column '{c}' has only one non-NA value; std set to 0.")
        else:
            means[c] = float(np.nanmean(arr))
            # sample standard deviation
            stds[c] = float(np.nanstd(arr, ddof=1))

    # ---- ANOVA ----
    anova_result = None
    if len(numeric_cols) >= 2:
        # prepare arrays for f_oneway; require at least 2 non-NA in each group
        groups = []
        for c in numeric_cols:
            vals = numeric_df[c].dropna().astype(float).values
            if vals.size >= 2:
                groups.append(vals)
            else:
                notes.append(f"Column '{c}' excluded from ANOVA because it has less than 2 non-NA values.")
        if len(groups) >= 2:
            try:
                F, p = f_oneway(*groups)
                anova_result = {'F': float(F), 'p': float(p)}
                if p < 0.05:
                    notes.append(f"ANOVA p={p:.4e} suggests significant differences among column means (alpha=0.05).")
                else:
                    notes.append(f"ANOVA p={p:.4e} suggests no significant differences (alpha=0.05).")
            except Exception as e:
                notes.append(f"ANOVA failed: {e}")
                anova_result = None
        else:
            notes.append("Not enough groups with >=2 observations to run ANOVA.")
    else:
        notes.append("ANOVA not run: need at least 2 numeric columns.")

    # ---- Histograms ----
    plot_files = []
    if plot_dir is not None:
        os.makedirs(plot_dir, exist_ok=True)

    for c in numeric_cols:
        arr = numeric_df[c].dropna().astype(float).values
        if arr.size == 0:
            continue
        plt.figure(figsize=(6,4))
        plt.hist(arr, bins=hist_bins, color='C0', edgecolor='black')
        plt.title(f"Histogram of {c}")
        plt.xlabel(c)
        plt.ylabel("Count")
        plt.grid(axis='y', alpha=0.3)
        if plot_dir is not None:
            fname = os.path.join(plot_dir, f"hist_{c.replace(os.sep, '_')}.png")
            plt.tight_layout()
            plt.savefig(fname, dpi=150)
            plot_files.append(fname)
            plt.close()
        else:
            if show_plots:
                plt.tight_layout()
                plt.show()
            else:
                plt.close()

    result = {
        'means': means,
        'stds': stds,
        'counts': counts,
        'anova': anova_result,
        'plot_files': plot_files,
        'notes': notes
    }
    return result
