def analyze_csv_numeric(csv_path, output_dir=None, show_plots=False):
    """
    Read CSV at csv_path, convert string representations of numbers (including commas
    used as thousands separators or decimal commas) into floats, compute mean & std
    for each numeric column, generate histogram plots (saved to output_dir or current dir),
    and perform a one-way ANOVA across numeric columns if there are at least two groups
    with >=2 observations each.

    Args:
        csv_path (str): Path to the CSV file.
        output_dir (str or None): Directory to save histogram PNGs. If None, uses current dir.
        show_plots (bool): If True, displays plots in addition to saving.

    Returns:
        dict: {
            'columns': {
                column_name: {'mean': float or None, 'std': float or None, 'n': int, 'hist_path': str or None}
                ...
            },
            'anova': {'F': float, 'p': float} or None
        }

    Notes:
        - Requires pandas, numpy, matplotlib, scipy.
        - Robust parsing supports formats like "1,234.56", "1.234,56", "1234,56", "1,234".
    """
    import os
    import re
    import math
    from collections import OrderedDict

    try:
        import pandas as pd
        import numpy as np
        import matplotlib.pyplot as plt
        from scipy import stats
    except Exception as e:
        raise ImportError("This function requires pandas, numpy, matplotlib, and scipy. "
                          "Install them (pip install pandas numpy matplotlib scipy).") from e

    if output_dir is None:
        output_dir = os.getcwd()
    else:
        os.makedirs(output_dir, exist_ok=True)

    # Helper: safe filename from column name
    def _safe_fname(name):
        name = str(name)
        name = re.sub(r'[^0-9A-Za-z._-]+', '_', name).strip('_')
        if not name:
            name = "col"
        return name

    # Helper: robust parse number strings that may contain commas/dots
    def _parse_number(value):
        if value is None:
            return np.nan
        # If already numeric type
        if isinstance(value, (int, float, np.integer, np.floating)) and not (isinstance(value, bool)):
            return float(value)
        s = str(value).strip()
        if s == "" or s.lower() in {"nan", "none", "na", "null", "-"}:
            return np.nan

        # Remove spaces and non-breaking spaces
        s = s.replace('\xa0', '').replace(' ', '')

        # Recognize parentheses negative e.g. (123.45)
        if s.startswith('(') and s.endswith(')'):
            s_val = s[1:-1]
            parsed = _parse_number(s_val)
            return -parsed if not np.isnan(parsed) else np.nan

        # If both '.' and ',' are present, decide decimal by last occurrence
        if '.' in s and ',' in s:
            last_dot = s.rfind('.')
            last_comma = s.rfind(',')
            if last_comma > last_dot:
                # comma is decimal separator, dot is thousands -> remove dots, replace comma with dot
                s2 = s.replace('.', '').replace(',', '.')
                try:
                    return float(s2)
                except:
                    return np.nan
            else:
                # dot is decimal, comma thousands -> remove commas
                s2 = s.replace(',', '')
                try:
                    return float(s2)
                except:
                    return np.nan

        # If only comma present
        if ',' in s and '.' not in s:
            parts = s.split(',')
            # If multiple commas, likely thousands separators -> remove all commas
            if len(parts) > 2:
                s2 = s.replace(',', '')
                try:
                    return float(s2)
                except:
                    return np.nan
            # If single comma, decide by length of fractional part
            if len(parts) == 2:
                frac = parts[1]
                # If fractional part length is 3 => probably thousands separator (e.g., "1,234")
                if len(frac) == 3:
                    s2 = s.replace(',', '')
                    try:
                        return float(s2)
                    except:
                        return np.nan
                else:
                    # treat comma as decimal separator
                    s2 = s.replace(',', '.')
                    try:
                        return float(s2)
                    except:
                        return np.nan
            # fallback
            try:
                return float(s.replace(',', ''))
            except:
                return np.nan

        # If only dot present or none present
        if '.' in s:
            # common decimal format
            try:
                return float(s)
            except:
                # fallback remove any stray thousands separators
                s2 = s.replace(',', '')
                try:
                    return float(s2)
                except:
                    return np.nan
        else:
            # no dot or comma: try integer like "1234"
            try:
                return float(s)
            except:
                # remove non-digit characters
                s2 = re.sub(r'[^\d\-\+eE.]', '', s)
                try:
                    return float(s2)
                except:
                    return np.nan

    # Read CSV with all columns as strings initially to control parsing
    df_raw = pd.read_csv(csv_path, dtype=str, keep_default_na=False, na_values=[''])
    # Convert each column
    df_conv = pd.DataFrame(index=df_raw.index)
    numeric_cols = []
    results = OrderedDict()

    for col in df_raw.columns:
        series = df_raw[col].astype(str).replace({'': None})
        # Apply parser
        parsed = series.map(_parse_number)
        # Convert to numeric dtype with NaN
        parsed = pd.to_numeric(parsed, errors='coerce')
        df_conv[col] = parsed

        non_na = parsed.dropna()
        n = int(non_na.size)
        if n >= 1:
            # consider as numeric column
            numeric_cols.append(col)

        # Prepare minimal column result; hist_path will be set later only if numeric
        results[col] = {'mean': None, 'std': None, 'n': int(n), 'hist_path': None}

