        std = float(np.std(vals, ddof=1)) if n > 1 else float('nan')

        fname = f"{_safe_fname(col)}_hist.png"
        hist_path = os.path.join(output_dir, fname)

        # Plot histogram
        plt.figure(figsize=(6,4))
        try:
            plt.hist(vals, bins='auto', color='C0', edgecolor='black', alpha=0.75)
        except Exception:
            plt.hist(vals, bins=10, color='C0', edgecolor='black', alpha=0.75)
        plt.title(f"Histogram of {col} (n={n})")
        plt.xlabel(col)
        plt.ylabel('Frequency')
        plt.tight_layout()
        plt.savefig(hist_path)
        if show_plots:
            plt.show()
        plt.close()

        results[col] = {'mean': mean, 'std': std if not math.isnan(std) else None, 'n': int(n), 'hist_path': hist_path}

    # Perform one-way ANOVA across numeric columns if applicable
    anova_result = None
    # Build groups that have at least 2 observations (ANOVA more reliable with >=2)
    groups = []
    group_names = []
    for col in numeric_cols:
        arr = df_conv[col].dropna().values.astype(float)
        if arr.size >= 2:
            groups.append(arr)
            group_names.append(col)
    if len(groups) >= 2:
        try:
            F, p = stats.f_oneway(*groups)
            anova_result = {'F': float(F), 'p': float(p), 'groups': group_names}
        except Exception as e:
            # If ANOVA fails (e.g., constant input), return None
            anova_result = {'error': str(e)}
    else:
        anova_result = None

    return {'columns': results, 'anova': anova_result}
