Function (works with seconds or milliseconds timestamps):

```python
def unix_to_tz_str(timestamp, tz_name='UTC', fmt='%Y-%m-%d %H:%M:%S'):
    """
    Convert a Unix timestamp to a formatted date/time string in the specified timezone.

    Parameters:
    - timestamp: int or float. Unix time in seconds (or milliseconds; milliseconds are auto-detected).
    - tz_name: string. Timezone name, e.g. 'UTC', 'America/New_York', 'Europe/London'.
    - fmt: str. strftime format string for the output.

    Returns:
    - formatted date/time string in the given timezone.

    Raises:
    - RuntimeError if neither zoneinfo nor pytz is available.
    - ValueError if the timezone name is invalid.
    """
    import datetime

    # Accept either seconds or milliseconds (auto-detect)
    ts = float(timestamp)
    # If timestamp appears to be in milliseconds, convert to seconds
    if abs(ts) > 1e12:
        ts /= 1000.0

    # Prefer zoneinfo (Python 3.9+), fallback to pytz if available
    try:
        from zoneinfo import ZoneInfo  # Python 3.9+
        def _to_tz(dt_utc, tzname):
            try:
                return dt_utc.astimezone(ZoneInfo(tzname))
            except Exception as exc:
                raise ValueError(f"Invalid timezone name: {tzname}") from exc
    except Exception:
        try:
            import pytz
            def _to_tz(dt_utc, tzname):
                try:
                    tz = pytz.timezone(tzname)
                except Exception as exc:
                    raise ValueError(f"Invalid timezone name: {tzname}") from exc
                return dt_utc.astimezone(tz)
        except Exception:
            raise RuntimeError(
                "Neither zoneinfo (Python 3.9+) nor pytz is available. "
                "Install pytz (`pip install pytz`) or use Python 3.9+."
            )

    # Create an aware UTC datetime and convert
    dt_utc = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
    dt_local = _to_tz(dt_utc, tz_name)
    return dt_local.strftime(fmt)
```

