import re
import socket
import urllib.parse
from collections import defaultdict

# Try to import requestkit; if not available, use requests as a fallback and wrap minimal behavior.
try:
    import requestkit as _rk  # type: ignore
    def _http_get(url, params=None, timeout=10):
