        def status_code(self):
            return self._resp.status_code
        def json(self):
            return self._resp.json()
        @property
        def text(self):
            return self._resp.text

    def _http_get(url, params=None, timeout=10):
        r = _requests.get(url, params=params, timeout=timeout)
        return _RespWrapper(r)


def extract_urls_and_geolocate(text, ip_api_base="http://ip-api.com/json/", timeout=8):
    """
    Extracts URLs from 'text', groups them by domain, resolves domain -> IP(s),
    and queries ip-api.com for geolocation info for each IP.

    Returns a dict:
      {
        "example.com": {
           "urls": [ ... list of original URLs that map to this domain ... ],
           "ips": ["93.184.216.34", ...],
           "geo": {
               "93.184.216.34": { ... ip-api JSON ... },
               ...
           },
           "errors": [ ... any error messages encountered for this domain ... ]
        },
        ...
      }

    Notes:
    - Uses ip-api.com (no API key) and is subject to its rate limits.
    - IPv4 addresses are resolved via socket.gethostbyname_ex; IPv6 is omitted for simplicity.
    """
    # Regex to find URLs. Captures http/https/ftp and also URLs that start with "www."
    url_regex = re.compile(
        r'\b(?:https?://|ftp://|www\.)[^\s<>"\']+',
        flags=re.IGNORECASE
    )

    found = url_regex.findall(text or "")
    # Map domain -> set(urls)
    domains_to_urls = defaultdict(set)

    for raw in found:
        candidate = raw
        # Ensure parseable URL
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*://', candidate):
            candidate = "http://" + candidate  # prepend scheme for parsing
        try:
            parts = urllib.parse.urlparse(candidate)
            netloc = parts.netloc
            # Remove possible credentials "user:pass@host"
            if "@" in netloc:
                netloc = netloc.split("@", 1)[1]
            # Remove port if any
            host = netloc.split(":", 1)[0].lower().rstrip(".")
            if host:
                domains_to_urls[host].add(raw)
        except Exception:
            # skip malformed
            continue

    results = {}
    for domain, urls in domains_to_urls.items():
        entry = {"urls": sorted(urls), "ips": [], "geo": {}, "errors": []}
        # Resolve domain to IPs (IPv4)
        ips = []
        try:
            # gethostbyname_ex returns (hostname, aliaslist, ipaddrlist)
            _, _, ip_list = socket.gethostbyname_ex(domain)
            # deduplicate while preserving
            seen = set()
            for ip in ip_list:
                if ip not in seen:
                    seen.add(ip)
                    ips.append(ip)
        except socket.gaierror as e:
            entry["errors"].append(f"DNS resolution failed: {e}")
        except Exception as e:
            entry["errors"].append(f"DNS error: {e}")

        entry["ips"] = ips

        # For each IP, query ip-api
        for ip in ips:
            try:
                resp = _http_get(f"{ip_api_base}{urllib.parse.quote(ip)}", timeout=timeout)
                if getattr(resp, "status_code", None) is not None and resp.status_code != 200:
                    entry["errors"].append(f"HTTP error for {ip}: status {resp.status_code}")
                    continue
                try:
                    data = resp.json()
                except Exception:
                    # Try to parse text as fallback
                    entry["errors"].append(f"Failed to parse JSON for {ip}")
                    continue
                entry["geo"][ip] = data
            except Exception as e:
                entry["errors"].append(f"Request failed for {ip}: {e}")

        results[domain] = entry

    return results


# Example usage
if __name__ == "__main__":
    sample_text = """
    Check these links:
    https://www.example.com/path?query=1
    http://example.com/another
    ftp://ftp.example.org/resource
    Visit www.python.org for more info.
    """
    out = extract_urls_and_geolocate(sample_text)
    import json
    print(json.dumps(out, indent=2))
