            domain_to_urls.setdefault(hostname.lower(), []).append(url)
        except Exception:
            continue

    results = {}
    for i, (domain, examples) in enumerate(domain_to_urls.items()):
        api_url = f"http://ip-api.com/json/{domain}?fields=status,message,country,regionName,city,lat,lon,isp,query,org,as,timezone"
        data, err = _http_get_json(api_url, timeout=timeout)
