Copy and run this as-is (it does internal imports). If you don't have requests/beautifulsoup4 installed, install them with: pip install requests beautifulsoup4

```
def extract_url_and_get_title(text: str) -> str:
    """
    Extract a URL from 'text', fetch the page, and return its <title> text.
    If no valid URL is found or the fetch fails / the page has no title,
    returns an informative error message.

    Note: Requires 'requests' and 'beautifulsoup4' (bs4). If they're not installed,
    the function returns an error message explaining how to install them.
    """
    try:
        import re
        from urllib.parse import urlparse
        import requests
        from bs4 import BeautifulSoup
    except Exception as e:
        return ("Missing required libraries. Please install with:\n"
                "  pip install requests beautifulsoup4\n"
                f"Import error: {e}")

    if not text or not isinstance(text, str):
        return "Input must be a non-empty string."

    # A reasonably permissive URL pattern: matches with or without scheme, includes path.
    url_pattern = re.compile(
        r'\b(?:https?://)?(?:www\.)?[a-z0-9-]+(?:\.[a-z0-9-]+)+(?::\d+)?(?:/[^\s\'"<>]*)?\b',
        re.IGNORECASE
    )

    m = url_pattern.search(text)
    if not m:
        return "No valid URL found in input text."

    url = m.group(0)

    # If the URL has no scheme, assume http
    parsed = urlparse(url)
    if not parsed.scheme:
        url = "http://" + url
        parsed = urlparse(url)

    # Basic sanity check
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return "Extracted string is not a valid HTTP/HTTPS URL."

    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; URLTitleFetcher/1.0; +https://example.com)"
    }

    try:
        resp = requests.get(url, headers=headers, timeout=10, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return f"Error fetching URL: {e}"

    if resp.status_code != 200:
        return f"Failed to fetch URL: HTTP {resp.status_code}"

    content_type = resp.headers.get("Content-Type", "")
    if "html" not in content_type.lower():
        # Some HTML pages may omit content-type; still try to parse, but warn if not html
        # We'll still attempt to parse if small chance.
        return f"URL did not return an HTML page (Content-Type: {content_type})."

    # Parse HTML and extract title
    try:
        soup = BeautifulSoup(resp.content, "html.parser")
    except Exception as e:
        return f"Failed to parse HTML: {e}"

    title_tag = soup.title
    if title_tag:
        title_text = title_tag.get_text(strip=True)
        if title_text:
            return title_text
        else:
            return "Title tag found but empty."
    else:
        # Try common fallbacks (meta og:title)
        og = soup.find("meta", property="og:title")
        if og and og.get("content"):
            return og.get("content").strip()
        twitter = soup.find("meta", attrs={"name": "twitter:title"})
        if twitter and twitter.get("content"):
            return twitter.get("content").strip()
        return "No <title> tag found in the page."

