      - If none found, looks for bare domains like 'example.com' and prepends 'http://'.
      - Fetches the URL with requests and parses the HTML title with BeautifulSoup.
      - Handles network errors, non-200 status codes, and missing <title>.
    """
    if not text or not isinstance(text, str):
        return {'success': False, 'error': 'Input must be a non-empty string.'}

    # 1) Try to find explicit URLs (http(s):// or www.)
    pattern_explicit = re.compile(r'(?i)\b((?:https?://|www\.)[^\s<>"\'()]+)')
    m = pattern_explicit.search(text)
    url = None

    if m:
        url = m.group(1).rstrip('.,;:!?)]')  # trim trailing punctuation commonly attached
    else:
        # 2) Fallback: detect bare domain like example.com or sub.example.co.uk[/path]
        # This will match things like "example.com", "sub.example.co.uk/path", etc.
        pattern_bare = re.compile(
            r'(?i)\b([A-Za-z0-9.-]+\.[A-Za-z]{2,})(/[^\s<>"\'()]*)?'
        )
        m2 = pattern_bare.search(text)
        if m2:
            domain = m2.group(1)
            path = m2.group(2) or ''
            url = domain + path
            # Trim punctuation
            url = url.rstrip('.,;:!?)]')

    if not url:
        return {'success': False, 'error': 'No valid URL found in the input text.'}

    # Normalize: ensure scheme present
    parsed = urlparse(url, scheme='')
    if not parsed.scheme:
        # If URL started with 'www.' or is a bare domain, prepend http://
        url = 'http://' + url
        parsed = urlparse(url)

    # Basic check: must have network location
    if not parsed.netloc:
        return {'success': False, 'error': f'Extracted URL appears invalid: {url}'}

    # Fetch the page
    headers = {
        'User-Agent': 'Mozilla/5.0 (compatible; url-title-extractor/1.0; +https://example.local/)'
    }
    try:
        resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return {'success': False, 'error': f'Failed to fetch URL: {e}'}

    if resp.status_code >= 400:
        return {'success': False, 'error': f'HTTP error fetching URL: status code {resp.status_code}'}

    content_type = resp.headers.get('Content-Type', '')
    if 'html' not in content_type.lower() and 'text' not in content_type.lower():
        # still try to parse in case server mislabels content
        pass

    # Parse HTML and extract <title>
    try:
        soup = BeautifulSoup(resp.text, 'html.parser')
    except Exception as e:
        return {'success': False, 'error': f'Failed to parse HTML: {e}'}

    title_tag = soup.find('title')
    if not title_tag or not title_tag.string:
        # Try alternative: look for og:title meta tag
        og = soup.find('meta', property='og:title') or soup.find('meta', attrs={'name': 'twitter:title'})
        og_title = og.get('content') if og and og.get('content') else None
        if og_title:
            title = og_title.strip()
            return {'success': True, 'url': resp.url, 'title': title}
        return {'success': False, 'error': 'Title tag not found in the page.'}

    title = title_tag.string.strip()
    if not title:
        return {'success': False, 'error': 'Title is empty.'}

    return {'success': True, 'url': resp.url, 'title': title}
