    ax.set_xticks(range(len(labels)))
    ax.set_xticklabels(labels, rotation=90)
    ax.set_xlabel('3-letter string')
    ax.set_ylabel('Frequency')
    ax.set_title(f'Top {len(labels)} most common 3-letter strings (n={n})')
    plt.tight_layout()

    if show:
        plt.show()

    return fig

